import { useState, useEffect, useRef, useCallback } from 'react'
import {
  Brain,
  FileText,
  Folder,
  FolderOpen,
  Plus,
  Trash2,
  Save,
  ChevronRight,
} from 'lucide-react'
import type { MemoryNode } from '../lib/api'
import {
  getMemoryTree,
  getMemoryFile,
  updateMemoryFile,
  createMemoryFile,
  deleteMemoryFile,
} from '../lib/api'
import { toast } from '../components/Toast'

// ── Types ──────────────────────────────────────────────────────────────────────

interface Frontmatter {
  type?: string
  [key: string]: unknown
}

// ── Helpers ────────────────────────────────────────────────────────────────────

function parseFrontmatter(content: string): { meta: Frontmatter; body: string } {
  const match = content.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/)
  if (!match) return { meta: {}, body: content }
  const meta: Frontmatter = {}
  for (const line of match[1].split('\n')) {
    const kv = line.match(/^(\w+):\s*(.*)$/)
    if (kv) meta[kv[1]] = kv[2].trim()
  }
  return { meta, body: match[2] }
}

function countChecklist(content: string): number {
  return (content.match(/^- \[/gm) ?? []).length
}

const MEMORY_TYPE_DESCRIPTIONS: Record<string, string> = {
  user: 'Who the user is — tailors future behavior',
  feedback: 'How to approach work — corrections and validations',
  project: 'Ongoing work context — goals, decisions, deadlines',
  reference: 'Pointers to external systems',
}

// ── File Tree ──────────────────────────────────────────────────────────────────

interface TreeNodeProps {
  node: MemoryNode
  selectedPath: string | null
  onSelect: (path: string) => void
  onDelete: (path: string) => void
}

function TreeNode({ node, selectedPath, onSelect, onDelete }: TreeNodeProps) {
  const [open, setOpen] = useState(true)
  const [hovering, setHovering] = useState(false)

  if (node.type === 'dir') {
    return (
      <div>
        <button
          onClick={() => setOpen((o) => !o)}
          className="flex items-center gap-1.5 w-full px-3 py-1.5 text-[13px] text-text-secondary hover:text-text hover:bg-surface-2 rounded-lg transition-colors"
        >
          <ChevronRight
            className={`w-3.5 h-3.5 shrink-0 transition-transform ${open ? 'rotate-90' : ''}`}
          />
          {open ? (
            <FolderOpen className="w-3.5 h-3.5 shrink-0 text-accent" />
          ) : (
            <Folder className="w-3.5 h-3.5 shrink-0 text-text-muted" />
          )}
          <span className="truncate font-medium">{node.name}</span>
        </button>
        {open && node.children && node.children.length > 0 && (
          <div className="ml-4 border-l border-border pl-2 mt-0.5 space-y-0.5">
            {node.children.map((child) => (
              <TreeNode
                key={child.path}
                node={child}
                selectedPath={selectedPath}
                onSelect={onSelect}
                onDelete={onDelete}
              />
            ))}
          </div>
        )}
      </div>
    )
  }

  const isSelected = selectedPath === node.path
  const Icon = node.name === 'MEMORY.md' ? Brain : FileText

  return (
    <div
      className="relative"
      onMouseEnter={() => setHovering(true)}
      onMouseLeave={() => setHovering(false)}
    >
      <button
        onClick={() => onSelect(node.path)}
        className={`flex items-center gap-2 w-full px-3 py-1.5 text-[13px] rounded-lg transition-colors text-left pr-8 ${
          isSelected
            ? 'bg-accent-muted text-accent-hover font-medium'
            : 'text-text-secondary hover:text-text hover:bg-surface-2'
        }`}
      >
        <Icon className="w-3.5 h-3.5 shrink-0" />
        <span className="truncate">{node.name}</span>
      </button>
      {hovering && (
        <button
          onClick={(e) => {
            e.stopPropagation()
            onDelete(node.path)
          }}
          className="absolute right-2 top-1/2 -translate-y-1/2 p-0.5 rounded text-text-muted hover:text-red-500 transition-colors"
          title="Delete file"
        >
          <Trash2 className="w-3.5 h-3.5" />
        </button>
      )}
    </div>
  )
}

// ── Info Sidebar ───────────────────────────────────────────────────────────────

interface InfoSidebarProps {
  filePath: string | null
  content: string
}

function InfoSidebar({ filePath, content }: InfoSidebarProps) {
  if (!filePath) {
    return (
      <div className="p-4">
        <p className="text-text-muted text-[13px]">Select a file to see details.</p>
      </div>
    )
  }

  const fileName = filePath.split('/').pop() ?? filePath
  const isIndex = fileName === 'MEMORY.md'
  const { meta } = parseFrontmatter(content)
  const memType = typeof meta.type === 'string' ? meta.type : undefined
  const checklistCount = isIndex ? countChecklist(content) : 0

  return (
    <div className="p-4 space-y-5">
      <div>
        <p className="text-[10px] font-semibold uppercase tracking-wider text-text-muted mb-2">
          File
        </p>
        <p className="text-[13px] font-medium text-text break-all">{fileName}</p>
        <p className="text-[12px] text-text-muted mt-1 break-all">{filePath}</p>
      </div>

      {isIndex && (
        <div>
          <p className="text-[10px] font-semibold uppercase tracking-wider text-text-muted mb-2">
            Index Stats
          </p>
          <div className="bg-surface-2 rounded-lg p-3">
            <p className="text-[13px] text-text">
              <span className="font-semibold text-accent">{checklistCount}</span> memory entries
            </p>
          </div>
        </div>
      )}

      {memType && MEMORY_TYPE_DESCRIPTIONS[memType] && (
        <div>
          <p className="text-[10px] font-semibold uppercase tracking-wider text-text-muted mb-2">
            Memory Type
          </p>
          <div className="bg-surface-2 rounded-lg p-3">
            <p className="text-[12px] font-semibold text-accent capitalize mb-1">{memType}</p>
            <p className="text-[12px] text-text-secondary leading-relaxed">
              {MEMORY_TYPE_DESCRIPTIONS[memType]}
            </p>
          </div>
        </div>
      )}

      <div>
        <p className="text-[10px] font-semibold uppercase tracking-wider text-text-muted mb-2">
          Memory Types
        </p>
        <div className="space-y-2">
          {Object.entries(MEMORY_TYPE_DESCRIPTIONS).map(([type, desc]) => (
            <div
              key={type}
              className={`rounded-lg p-2.5 ${
                memType === type ? 'bg-accent-muted border border-accent/30' : 'bg-surface-2'
              }`}
            >
              <p className="text-[11px] font-semibold text-text capitalize mb-0.5">{type}</p>
              <p className="text-[11px] text-text-muted leading-relaxed">{desc}</p>
            </div>
          ))}
        </div>
      </div>
    </div>
  )
}

// ── New File Form ──────────────────────────────────────────────────────────────

interface NewFileFormProps {
  onSubmit: (filePath: string) => Promise<void>
  onCancel: () => void
}

function NewFileForm({ onSubmit, onCancel }: NewFileFormProps) {
  const [value, setValue] = useState('')
  const [creating, setCreating] = useState(false)
  const inputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    inputRef.current?.focus()
  }, [])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    const trimmed = value.trim()
    if (!trimmed) return
    setCreating(true)
    await onSubmit(trimmed)
    setCreating(false)
  }

  return (
    <form onSubmit={handleSubmit} className="px-3 pb-3">
      <input
        ref={inputRef}
        value={value}
        onChange={(e) => setValue(e.target.value)}
        placeholder="e.g. user/new-memory.md"
        className="w-full px-2.5 py-1.5 text-[12px] bg-surface border border-accent/50 rounded-lg text-text placeholder:text-text-muted focus:outline-none focus:border-accent font-mono"
      />
      <div className="flex gap-1.5 mt-1.5">
        <button
          type="submit"
          disabled={creating || !value.trim()}
          className="flex-1 py-1 text-[11px] font-medium bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
        >
          {creating ? 'Creating...' : 'Create'}
        </button>
        <button
          type="button"
          onClick={onCancel}
          className="flex-1 py-1 text-[11px] font-medium bg-surface-2 text-text-secondary rounded-lg hover:text-text transition-colors"
        >
          Cancel
        </button>
      </div>
    </form>
  )
}

// ── Main Page ──────────────────────────────────────────────────────────────────

export default function Memory() {
  const [tree, setTree] = useState<MemoryNode[]>([])
  const [treeLoading, setTreeLoading] = useState(true)
  const [selectedPath, setSelectedPath] = useState<string | null>(null)
  const [content, setContent] = useState('')
  const [savedContent, setSavedContent] = useState('')
  const [fileLoading, setFileLoading] = useState(false)
  const [saving, setSaving] = useState(false)
  const [showNewForm, setShowNewForm] = useState(false)

  const dirty = content !== savedContent

  // Load tree
  const loadTree = useCallback(async () => {
    try {
      const data = await getMemoryTree()
      setTree(data)
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to load memory tree')
    } finally {
      setTreeLoading(false)
    }
  }, [])

  useEffect(() => {
    loadTree()
  }, [loadTree])

  // Load file
  const handleSelectFile = useCallback(async (filePath: string) => {
    if (dirty) {
      const confirmed = window.confirm('You have unsaved changes. Discard them?')
      if (!confirmed) return
    }
    setSelectedPath(filePath)
    setFileLoading(true)
    setContent('')
    setSavedContent('')
    try {
      const data = await getMemoryFile(filePath)
      setContent(data.content)
      setSavedContent(data.content)
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to load file')
    } finally {
      setFileLoading(false)
    }
  }, [dirty])

  // Save file
  const handleSave = useCallback(async () => {
    if (!selectedPath || !dirty) return
    setSaving(true)
    try {
      await updateMemoryFile(selectedPath, content)
      setSavedContent(content)
      toast('success', 'Saved')
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to save')
    } finally {
      setSaving(false)
    }
  }, [selectedPath, content, dirty])

  // Cmd+S
  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 's') {
        e.preventDefault()
        handleSave()
      }
    }
    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [handleSave])

  // Delete file
  const handleDelete = useCallback(async (filePath: string) => {
    const confirmed = window.confirm(`Delete ${filePath}?`)
    if (!confirmed) return
    try {
      await deleteMemoryFile(filePath)
      toast('success', 'Deleted')
      if (selectedPath === filePath) {
        setSelectedPath(null)
        setContent('')
        setSavedContent('')
      }
      loadTree()
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to delete')
    }
  }, [selectedPath, loadTree])

  // Create file
  const handleCreateFile = useCallback(async (filePath: string) => {
    try {
      await createMemoryFile(filePath)
      toast('success', 'Created')
      setShowNewForm(false)
      await loadTree()
      handleSelectFile(filePath)
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to create file')
    }
  }, [loadTree, handleSelectFile])

  // Breadcrumb
  const breadcrumbs = selectedPath ? selectedPath.split('/') : []

  return (
    <div className="flex h-screen overflow-hidden">
      {/* Left panel — file tree */}
      <aside className="w-[240px] min-w-[240px] border-r border-border bg-surface flex flex-col h-full">
        <div className="px-4 py-3 border-b border-border flex items-center justify-between shrink-0">
          <div className="flex items-center gap-2">
            <Brain className="w-4 h-4 text-accent" />
            <span className="text-[13px] font-semibold tracking-tight">Memory Brain</span>
          </div>
          <button
            onClick={() => setShowNewForm((v) => !v)}
            title="New file"
            className="p-1 rounded-lg text-text-muted hover:text-accent hover:bg-surface-2 transition-colors"
          >
            <Plus className="w-4 h-4" />
          </button>
        </div>

        {showNewForm && (
          <div className="border-b border-border py-2">
            <NewFileForm onSubmit={handleCreateFile} onCancel={() => setShowNewForm(false)} />
          </div>
        )}

        <div className="flex-1 overflow-y-auto py-2 px-2 space-y-0.5">
          {treeLoading ? (
            <div className="flex items-center justify-center py-8">
              <div className="w-5 h-5 border-2 border-accent border-t-transparent rounded-full animate-spin" />
            </div>
          ) : tree.length === 0 ? (
            <p className="text-text-muted text-[12px] px-3 py-4">No memory files found.</p>
          ) : (
            tree.map((node) => (
              <TreeNode
                key={node.path}
                node={node}
                selectedPath={selectedPath}
                onSelect={handleSelectFile}
                onDelete={handleDelete}
              />
            ))
          )}
        </div>
      </aside>

      {/* Middle panel — editor */}
      <main className="flex-1 min-w-0 flex flex-col h-full bg-surface">
        {/* Editor header */}
        <div className="px-5 py-3 border-b border-border flex items-center justify-between shrink-0">
          <div className="flex items-center gap-1.5 text-[12px] text-text-muted min-w-0">
            {breadcrumbs.length === 0 ? (
              <span className="text-text-muted italic">No file selected</span>
            ) : (
              breadcrumbs.map((crumb, i) => (
                <span key={i} className="flex items-center gap-1.5">
                  {i > 0 && <ChevronRight className="w-3 h-3 shrink-0" />}
                  <span
                    className={
                      i === breadcrumbs.length - 1
                        ? 'text-text font-medium'
                        : 'text-text-muted'
                    }
                  >
                    {crumb}
                  </span>
                </span>
              ))
            )}
          </div>
          <div className="flex items-center gap-2 shrink-0 ml-4">
            {dirty && (
              <span className="w-2 h-2 rounded-full bg-accent shrink-0" title="Unsaved changes" />
            )}
            <button
              onClick={handleSave}
              disabled={!dirty || saving}
              className="flex items-center gap-1.5 px-3 py-1.5 text-[12px] font-medium bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
            >
              <Save className="w-3.5 h-3.5" />
              {saving ? 'Saving...' : 'Save'}
            </button>
            <span className="text-[11px] text-text-muted hidden sm:block">Cmd+S</span>
          </div>
        </div>

        {/* Textarea */}
        <div className="flex-1 min-h-0 p-4">
          {!selectedPath ? (
            <div className="flex items-center justify-center h-full">
              <div className="text-center space-y-2">
                <Brain className="w-10 h-10 text-text-muted mx-auto" />
                <p className="text-text-secondary text-[14px]">Select a file to edit</p>
                <p className="text-text-muted text-[12px]">
                  Choose a memory file from the left panel
                </p>
              </div>
            </div>
          ) : fileLoading ? (
            <div className="flex items-center justify-center h-full">
              <div className="w-6 h-6 border-2 border-accent border-t-transparent rounded-full animate-spin" />
            </div>
          ) : (
            <textarea
              value={content}
              onChange={(e) => setContent(e.target.value)}
              className="w-full h-full bg-surface border border-border rounded-xl p-4 font-mono text-sm text-text resize-none focus:outline-none focus:border-accent/50 transition-colors leading-relaxed"
              spellCheck={false}
              placeholder="Start writing..."
            />
          )}
        </div>
      </main>

      {/* Right panel — info sidebar */}
      <aside className="w-[260px] min-w-[260px] border-l border-border bg-surface flex flex-col h-full overflow-y-auto">
        <div className="px-4 py-3 border-b border-border shrink-0">
          <p className="text-[13px] font-semibold tracking-tight">Info</p>
        </div>
        <InfoSidebar filePath={selectedPath} content={content} />
      </aside>
    </div>
  )
}

import type { Agent, AppConfig, Project, UnifiedAgent, UnifiedCommand, UnifiedRule } from '../types'

const BASE = '/api'

async function request<T>(path: string, options?: RequestInit): Promise<T> {
  const res = await fetch(`${BASE}${path}`, {
    headers: { 'Content-Type': 'application/json' },
    ...options,
  })
  if (!res.ok) {
    const data = await res.json().catch(() => ({ error: `HTTP ${res.status}` }))
    throw new Error(data.error || `API error: ${res.status}`)
  }
  return res.json()
}

// Sanitize name for safe file creation
export function sanitizeName(name: string): string {
  return name
    .trim()
    .toLowerCase()
    .replace(/\s+/g, '-')
    .replace(/[^a-z0-9_-]/g, '')
    .replace(/^-+|-+$/g, '')
}

// Config
export const getConfig = () => request<AppConfig>('/config')
export const updateProjectDirs = (dirs: string[]) =>
  request('/config/project-dirs', { method: 'POST', body: JSON.stringify({ dirs }) })

// Global CLAUDE.md
export const getGlobalClaudeMd = () =>
  request<{ content: string; exists: boolean }>('/global/claude-md')
export const updateGlobalClaudeMd = (content: string) =>
  request('/global/claude-md', { method: 'PUT', body: JSON.stringify({ content }) })

// Global Agents
export const getGlobalAgents = () => request<Agent[]>('/global/agents')
export const getGlobalAgent = (name: string) => request<Agent>(`/global/agents/${name}`)
export const updateGlobalAgent = (name: string, content: string) =>
  request(`/global/agents/${name}`, { method: 'PUT', body: JSON.stringify({ content }) })
export const deleteGlobalAgent = (name: string) =>
  request(`/global/agents/${name}`, { method: 'DELETE' })

// Global Settings
export const getGlobalSettings = () => request<Record<string, unknown>>('/global/settings')
export const updateGlobalSettings = (settings: Record<string, unknown>) =>
  request('/global/settings', { method: 'PUT', body: JSON.stringify({ settings }) })

// Projects
export const getProjects = () => request<Project[]>('/projects')

// Project CLAUDE.md
export const getProjectClaudeMd = (id: string) =>
  request<{ content: string; exists: boolean; path: string }>(`/projects/${id}/claude-md`)
export const updateProjectClaudeMd = (id: string, content: string) =>
  request(`/projects/${id}/claude-md`, { method: 'PUT', body: JSON.stringify({ content }) })

// Project Agents
export const getProjectAgents = (id: string) => request<Agent[]>(`/projects/${id}/agents`)
export const getProjectAgent = (id: string, name: string) =>
  request<Agent>(`/projects/${id}/agents/${name}`)
export const updateProjectAgent = (id: string, name: string, content: string) =>
  request(`/projects/${id}/agents/${name}`, { method: 'PUT', body: JSON.stringify({ content }) })
export const deleteProjectAgent = (id: string, name: string) =>
  request(`/projects/${id}/agents/${name}`, { method: 'DELETE' })

// Project Commands (full CRUD)
export interface MdFile {
  name: string
  content: string
  path: string
  updatedAt: string
}
export const getProjectCommands = (id: string) => request<MdFile[]>(`/projects/${id}/commands`)
export const getProjectCommand = (id: string, name: string) =>
  request<MdFile>(`/projects/${id}/commands/${name}`)
export const updateProjectCommand = (id: string, name: string, content: string) =>
  request(`/projects/${id}/commands/${name}`, { method: 'PUT', body: JSON.stringify({ content }) })
export const deleteProjectCommand = (id: string, name: string) =>
  request(`/projects/${id}/commands/${name}`, { method: 'DELETE' })

// Project Rules (full CRUD)
export const getProjectRules = (id: string) => request<MdFile[]>(`/projects/${id}/rules`)
export const getProjectRule = (id: string, name: string) =>
  request<MdFile>(`/projects/${id}/rules/${name}`)
export const updateProjectRule = (id: string, name: string, content: string) =>
  request(`/projects/${id}/rules/${name}`, { method: 'PUT', body: JSON.stringify({ content }) })
export const deleteProjectRule = (id: string, name: string) =>
  request(`/projects/${id}/rules/${name}`, { method: 'DELETE' })

// Copy / Move agent
export const copyAgent = (from: string, to: string, agentName: string) =>
  request('/copy-agent', { method: 'POST', body: JSON.stringify({ from, to, agentName }) })
export const moveAgent = (from: string, to: string, agentName: string) =>
  request('/move-agent', { method: 'POST', body: JSON.stringify({ from, to, agentName }) })

// Directory browser
export interface BrowseResult {
  current: string
  displayPath: string
  parent: string | null
  breadcrumbs: { name: string; path: string }[]
  directories: { name: string; path: string; displayPath: string; hasProjects: boolean }[]
}
export const browseDirectory = (dirPath?: string) =>
  request<BrowseResult>(`/browse${dirPath ? `?path=${encodeURIComponent(dirPath)}` : ''}`)

// Unified endpoints
export const getUnifiedAgents = () => request<UnifiedAgent[]>('/unified/agents')
export const getUnifiedCommands = () => request<UnifiedCommand[]>('/unified/commands')
export const getUnifiedRules = () => request<UnifiedRule[]>('/unified/rules')

// Claude AI
export interface AiMessage {
  role: 'user' | 'assistant'
  content: string
}

export interface AiSession {
  id: string
  title: string
  messages: AiMessage[]
  createdAt: string
  updatedAt: string
  messageCount?: number
}

export const sendAiChat = (messages: AiMessage[], system?: string) =>
  request<{ content: string }>('/ai/chat', {
    method: 'POST',
    body: JSON.stringify({ messages, system }),
  })

export async function streamAiChat(
  messages: AiMessage[],
  system: string | undefined,
  onChunk: (text: string) => void,
  signal?: AbortSignal,
): Promise<string> {
  const res = await fetch(`${BASE}/ai/stream`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ messages, system }),
    signal,
  })
  if (!res.ok) {
    const data = await res.json().catch(() => ({ error: `HTTP ${res.status}` }))
    throw new Error(data.error || `API error: ${res.status}`)
  }
  const reader = res.body!.getReader()
  const decoder = new TextDecoder()
  let buffer = ''
  let fullContent = ''

  while (true) {
    const { done, value } = await reader.read()
    if (done) break
    buffer += decoder.decode(value, { stream: true })
    const parts = buffer.split('\n')
    buffer = parts.pop() ?? ''
    for (const line of parts) {
      const trimmed = line.trim()
      if (!trimmed.startsWith('data: ')) continue
      try {
        const event = JSON.parse(trimmed.slice(6))
        if (event.type === 'chunk') {
          fullContent += event.content
          onChunk(event.content)
        } else if (event.type === 'done') {
          fullContent = event.content
        } else if (event.type === 'error') {
          throw new Error(event.error)
        }
      } catch (e) {
        if (e instanceof SyntaxError) continue
        throw e
      }
    }
  }
  return fullContent
}

// History
export const getAiHistory = () => request<AiSession[]>('/ai/history')
export const getAiSession = (id: string) => request<AiSession>(`/ai/history/${id}`)
export const saveAiSession = (session: { id?: string; title: string; messages: AiMessage[] }) =>
  request<{ id: string }>('/ai/history', { method: 'POST', body: JSON.stringify(session) })
export const deleteAiSession = (id: string) =>
  request(`/ai/history/${id}`, { method: 'DELETE' })

// Orchestration Run History
export interface RunHistoryItem {
  id: string
  orchestrationName: string
  orchestrationId: string | null
  task: string
  status: 'completed' | 'failed' | 'cancelled'
  nodeCount: number
  startedAt: string
  completedAt: string
  duration: number
}

export interface RunHistoryDetail extends RunHistoryItem {
  nodes: { id: string; label: string; agentName?: string; isStart?: boolean; isCustom?: boolean }[]
  edges: { source: string; target: string }[]
  logs: { nodeId: string | null; label: string | null; type: string; output?: string; error?: string; finalOutput?: string }[]
  nodeOutputs: Record<string, string>
  finalOutput: string
}

export const getRunHistory = () => request<RunHistoryItem[]>('/orchestrations/runs')
export const getRunDetail = (id: string) => request<RunHistoryDetail>(`/orchestrations/runs/${id}`)
export const deleteRun = (id: string) => request(`/orchestrations/runs/${id}`, { method: 'DELETE' })
export const clearRunHistory = () => request('/orchestrations/runs', { method: 'DELETE' })

// Full app context
export interface AppContext {
  globalClaudeMd: { path: string; content: string }
  globalAgentsDir: string
  globalAgents: { name: string; description: string; path: string; content: string }[]
  projects: {
    name: string
    path: string
    agentsDir: string
    commandsDir: string
    rulesDir: string
    claudeMd: { path: string; content: string }
    agents: { name: string; description: string; path: string; content: string }[]
    commands: { name: string; path: string; content: string }[]
    rules: { name: string; path: string; content: string }[]
  }[]
}
export const getAiContext = () => request<AppContext>('/ai/context')

// Apply AI file suggestion
export const applyAiFile = (filePath: string, content: string) =>
  request('/ai/apply', { method: 'POST', body: JSON.stringify({ filePath, content }) })

// Memory Brain
export interface MemoryNode {
  type: 'file' | 'dir'
  name: string
  path: string
  children?: MemoryNode[]
}

export const getMemoryTree = () => request<MemoryNode[]>('/memory')
export const getMemoryFile = (filePath: string) =>
  request<{ path: string; content: string }>(`/memory/file?path=${encodeURIComponent(filePath)}`)
export const updateMemoryFile = (filePath: string, content: string) =>
  request('/memory/file', { method: 'PUT', body: JSON.stringify({ path: filePath, content }) })
export const createMemoryFile = (filePath: string) =>
  request('/memory/file', { method: 'POST', body: JSON.stringify({ path: filePath }) })
export const deleteMemoryFile = (filePath: string) =>
  request(`/memory/file?path=${encodeURIComponent(filePath)}`, { method: 'DELETE' })

// Docs
export interface DocMeta {
  slug: string
  filename: string
  title: string
  description: string
}
export const getDocs = () => request<DocMeta[]>('/docs')
export const getDoc = (slug: string) => request<{ slug: string; content: string }>(`/docs/${slug}`)

