// ── Create Dialog ─────────────────────────────────────────────────────────────

function CreateDialog({
  mode,
  onSubmit,
  onCancel,
}: {
  mode: 'file' | 'folder'
  onSubmit: (path: string) => Promise<void>
  onCancel: () => void
}) {
  const [value, setValue] = useState('')
  const [creating, setCreating] = useState(false)
  const inputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    inputRef.current?.focus()
  }, [])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    const trimmed = value.trim()
    if (!trimmed) return
    setCreating(true)
    await onSubmit(trimmed)
    setCreating(false)
  }

  return (
    <form onSubmit={handleSubmit} className="px-3 py-2 border-b border-border bg-surface-2/50">
      <div className="flex items-center gap-2 mb-1.5">
        {mode === 'file' ? (
          <FileText className="w-3.5 h-3.5 text-accent" />
        ) : (
          <FolderPlus className="w-3.5 h-3.5 text-accent" />
        )}
        <span className="text-[11px] font-semibold text-text-secondary uppercase tracking-wider">
          New {mode}
        </span>
      </div>
      <input
        ref={inputRef}
        value={value}
        onChange={(e) => setValue(e.target.value)}
        placeholder={mode === 'file' ? 'e.g. user/new-memory.md' : 'e.g. projects/new-project'}
        className="w-full px-2.5 py-1.5 text-[12px] bg-surface border border-border rounded-lg text-text placeholder:text-text-muted focus:outline-none focus:border-accent font-mono"
      />
      <div className="flex gap-1.5 mt-1.5">
        <button
          type="submit"
          disabled={creating || !value.trim()}
          className="flex-1 py-1 text-[11px] font-medium bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
        >
          {creating ? 'Creating...' : 'Create'}
        </button>
        <button
          type="button"
          onClick={onCancel}
          className="flex-1 py-1 text-[11px] font-medium bg-surface-2 text-text-secondary rounded-lg hover:text-text transition-colors"
        >
          Cancel
        </button>
      </div>
    </form>
  )
}

// ── Rename Dialog ─────────────────────────────────────────────────────────────

function RenameDialog({
  currentPath,
  isDir,
  onSubmit,
  onCancel,
}: {
  currentPath: string
  isDir: boolean
  onSubmit: (newPath: string) => Promise<void>
  onCancel: () => void
}) {
  const currentName = currentPath.split('/').pop() ?? currentPath
  const parentPath = currentPath.includes('/') ? currentPath.slice(0, currentPath.lastIndexOf('/')) : ''
  const [value, setValue] = useState(currentName)
  const [saving, setSaving] = useState(false)
  const inputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    inputRef.current?.focus()
    inputRef.current?.select()
  }, [])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    const trimmed = value.trim()
    if (!trimmed || trimmed === currentName) return
    const newPath = parentPath ? `${parentPath}/${trimmed}` : trimmed
    setSaving(true)
    await onSubmit(newPath)
    setSaving(false)
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40">
      <form
        onSubmit={handleSubmit}
        className="bg-surface border border-border rounded-xl p-4 w-80 shadow-xl"
      >
        <p className="text-[13px] font-semibold text-text mb-3">
          Rename {isDir ? 'Folder' : 'File'}
        </p>
        <input
          ref={inputRef}
          value={value}
          onChange={(e) => setValue(e.target.value)}
          className="w-full px-3 py-2 text-[13px] bg-surface-2 border border-border rounded-lg text-text focus:outline-none focus:border-accent font-mono"
        />
        <div className="flex gap-2 mt-3">
          <button
            type="submit"
            disabled={saving || !value.trim() || value.trim() === currentName}
            className="flex-1 py-1.5 text-[12px] font-medium bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
          >
            {saving ? 'Renaming...' : 'Rename'}
          </button>
          <button
            type="button"
            onClick={onCancel}
            className="flex-1 py-1.5 text-[12px] font-medium bg-surface-2 text-text-secondary rounded-lg hover:text-text transition-colors"
          >
            Cancel
          </button>
        </div>
      </form>
    </div>
  )
}

// ── Main Page ─────────────────────────────────────────────────────────────────

export default function Memory() {
  // Core state
  const [tree, setTree] = useState<MemoryNode[]>([])
  const [treeLoading, setTreeLoading] = useState(true)
  const [selectedPath, setSelectedPath] = useState<string | null>(null)
  const [content, setContent] = useState('')
  const [savedContent, setSavedContent] = useState('')
  const [fileLoading, setFileLoading] = useState(false)
  const [saving, setSaving] = useState(false)

  // Search
  const [searchQuery, setSearchQuery] = useState('')
  const [searchResults, setSearchResults] = useState<MemorySearchResult[] | null>(null)
  const [searchLoading, setSearchLoading] = useState(false)
  const searchTimeout = useRef<ReturnType<typeof setTimeout>>()
  const searchInputRef = useRef<HTMLInputElement>(null)

  // Filters
  const [typeFilter, setTypeFilter] = useState<string | null>(null)
  const [showFilters, setShowFilters] = useState(false)

  // Create / rename
  const [createMode, setCreateMode] = useState<'file' | 'folder' | null>(null)
  const [renamingPath, setRenamingPath] = useState<{ path: string; isDir: boolean } | null>(null)

  // Stats
  const [stats, setStats] = useState<MemoryStats | null>(null)

  // Right panel view
  const [rightPanel, setRightPanel] = useState<'info' | 'stats'>('info')

  const dirty = content !== savedContent

  // Find selected node
  const selectedNode = useMemo(() => {
    if (!selectedPath) return null
    const allFiles = flattenNodes(tree)
    return allFiles.find((f) => f.path === selectedPath) ?? null
  }, [tree, selectedPath])

  // ── Data loading ──────────────────────────────────────────────────────────

  const loadTree = useCallback(async () => {
    try {
      const data = await getMemoryTree()
      setTree(data)
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to load memory tree')
    } finally {
      setTreeLoading(false)
    }
  }, [])

  const loadStats = useCallback(async () => {
    try {
      const data = await getMemoryStats()
      setStats(data)
    } catch {}
  }, [])

  useEffect(() => {
    loadTree()
    loadStats()
  }, [loadTree, loadStats])

  // ── Search ────────────────────────────────────────────────────────────────

  const handleSearch = useCallback(
    (query: string) => {
      setSearchQuery(query)
      if (searchTimeout.current) clearTimeout(searchTimeout.current)
      if (!query.trim()) {
        setSearchResults(null)
        return
      }
      setSearchLoading(true)
      searchTimeout.current = setTimeout(async () => {
        try {
          const results = await searchMemory(query.trim())
          setSearchResults(results)
        } catch {
          setSearchResults([])
        } finally {
          setSearchLoading(false)
        }
      }, 300)
    },
    [],
  )

  // Keyboard shortcut: Cmd+K to focus search
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault()
        searchInputRef.current?.focus()
      }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [])

  // ── File operations ───────────────────────────────────────────────────────

  const handleSelectFile = useCallback(
    async (filePath: string) => {
      if (dirty) {
        const confirmed = window.confirm('You have unsaved changes. Discard them?')
        if (!confirmed) return
      }
      setSelectedPath(filePath)
      setFileLoading(true)
      setContent('')
      setSavedContent('')
      setRightPanel('info')
      try {
        const data = await getMemoryFile(filePath)
        setContent(data.content)
        setSavedContent(data.content)
      } catch (err) {
        toast('error', err instanceof Error ? err.message : 'Failed to load file')
      } finally {
        setFileLoading(false)
      }
    },
    [dirty],
  )

  const handleSave = useCallback(async () => {
    if (!selectedPath || !dirty) return
    setSaving(true)
    try {
      await updateMemoryFile(selectedPath, content)
      setSavedContent(content)
      toast('success', 'Saved')
      loadTree() // Refresh tree to update frontmatter
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to save')
    } finally {
      setSaving(false)
    }
  }, [selectedPath, content, dirty, loadTree])

  // Cmd+S
  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 's') {
        e.preventDefault()
        handleSave()
      }
    }
    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [handleSave])

  const handleDelete = useCallback(
    async (filePath: string, isDir: boolean) => {
      const confirmed = window.confirm(
        `Delete ${isDir ? 'folder' : 'file'} "${filePath}"?${isDir ? ' (must be empty)' : ''}`,
      )
      if (!confirmed) return
      try {
        if (isDir) {
          await deleteMemoryFolder(filePath)
        } else {
          await deleteMemoryFile(filePath)
        }
        toast('success', 'Deleted')
        if (selectedPath === filePath) {
          setSelectedPath(null)
          setContent('')
          setSavedContent('')
        }
        loadTree()
        loadStats()
      } catch (err) {
        toast('error', err instanceof Error ? err.message : 'Failed to delete')
      }
    },
    [selectedPath, loadTree, loadStats],
  )

  const handleCreate = useCallback(
    async (filePath: string) => {
      try {
        if (createMode === 'folder') {
          await createMemoryFolder(filePath)
        } else {
          await createMemoryFile(filePath)
        }
        toast('success', `${createMode === 'folder' ? 'Folder' : 'File'} created`)
        setCreateMode(null)
        await loadTree()
        loadStats()
        if (createMode === 'file') {
          handleSelectFile(filePath)
        }
      } catch (err) {
        toast('error', err instanceof Error ? err.message : 'Failed to create')
      }
    },
    [createMode, loadTree, loadStats, handleSelectFile],
  )

  const handleRename = useCallback(
    async (newPath: string) => {
      if (!renamingPath) return
      try {
        await moveMemoryFile(renamingPath.path, newPath)
        toast('success', 'Renamed')
        if (selectedPath === renamingPath.path) {
          setSelectedPath(newPath)
          // Reload file content for new path
          const data = await getMemoryFile(newPath)
          setContent(data.content)
          setSavedContent(data.content)
        }
        setRenamingPath(null)
        loadTree()
        loadStats()
      } catch (err) {
        toast('error', err instanceof Error ? err.message : 'Failed to rename')
      }
    },
    [renamingPath, selectedPath, loadTree, loadStats],
  )

  // ── Breadcrumbs ───────────────────────────────────────────────────────────

  const breadcrumbs = selectedPath ? selectedPath.split('/') : []

  // ── Render ────────────────────────────────────────────────────────────────

  return (
    <div className="flex h-screen overflow-hidden bg-bg">
      {/* ═══ Left Panel — File Tree ═══ */}
      <aside className="w-[280px] min-w-[280px] border-r border-border bg-surface flex flex-col h-full">
        {/* Header */}
        <div className="px-3 py-3 border-b border-border shrink-0">
          <div className="flex items-center justify-between mb-2.5">
            <div className="flex items-center gap-2">
              <Brain className="w-4.5 h-4.5 text-accent" />
              <span className="text-[14px] font-bold tracking-tight">Memory Brain</span>
            </div>
            <div className="flex items-center gap-0.5">
              <button
                onClick={() => setCreateMode(createMode === 'folder' ? null : 'folder')}
                title="New folder"
                className={`p-1.5 rounded-lg transition-colors ${createMode === 'folder' ? 'bg-accent-muted text-accent' : 'text-text-muted hover:text-accent hover:bg-surface-2'}`}
              >
                <FolderPlus className="w-3.5 h-3.5" />
              </button>
              <button
                onClick={() => setCreateMode(createMode === 'file' ? null : 'file')}
                title="New file"
                className={`p-1.5 rounded-lg transition-colors ${createMode === 'file' ? 'bg-accent-muted text-accent' : 'text-text-muted hover:text-accent hover:bg-surface-2'}`}
              >
                <Plus className="w-3.5 h-3.5" />
              </button>
              <button
                onClick={() => {
                  setTreeLoading(true)
                  loadTree().finally(() => setTreeLoading(false))
                  loadStats()
                }}
                title="Refresh"
                className="p-1.5 rounded-lg text-text-muted hover:text-accent hover:bg-surface-2 transition-colors"
              >
                <RefreshCw className="w-3.5 h-3.5" />
              </button>
            </div>
          </div>

          {/* Search bar */}
          <div className="relative">
            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-text-muted pointer-events-none" />
            <input
              ref={searchInputRef}
              value={searchQuery}
              onChange={(e) => handleSearch(e.target.value)}
              placeholder="Search memory... (Cmd+K)"
              className="w-full pl-8 pr-8 py-1.5 text-[12px] bg-surface-2 border border-border rounded-lg text-text placeholder:text-text-muted focus:outline-none focus:border-accent transition-colors"
            />
            {searchQuery && (
              <button
                onClick={() => {
                  setSearchQuery('')
                  setSearchResults(null)
                }}
                className="absolute right-2 top-1/2 -translate-y-1/2 p-0.5 rounded text-text-muted hover:text-text"
              >
                <X className="w-3 h-3" />
              </button>
            )}
            {searchLoading && (
              <div className="absolute right-2 top-1/2 -translate-y-1/2">
                <div className="w-3 h-3 border-2 border-accent border-t-transparent rounded-full animate-spin" />
              </div>
            )}
            {/* Search results dropdown */}
            {searchResults !== null && searchQuery && (
              <SearchResults
                results={searchResults}
                query={searchQuery}
                onSelect={handleSelectFile}
                onClose={() => {
                  setSearchResults(null)
                  setSearchQuery('')
                }}
              />
            )}
          </div>
        </div>

        {/* Filter pills */}
        <div className="px-3 py-2 border-b border-border shrink-0">
          <div className="flex items-center gap-1 flex-wrap">
            <button
              onClick={() => setTypeFilter(null)}
              className={`px-2 py-0.5 text-[10px] font-medium rounded-md transition-colors ${
                !typeFilter
                  ? 'bg-accent-muted text-accent'
                  : 'text-text-muted hover:text-text hover:bg-surface-2'
              }`}
            >
              All
            </button>
            {MEMORY_TYPES.map((type) => {
              const m = TYPE_META[type]
              const isActive = typeFilter === type
              return (
                <button
                  key={type}
                  onClick={() => setTypeFilter(isActive ? null : type)}
                  className={`flex items-center gap-1 px-2 py-0.5 text-[10px] font-medium rounded-md transition-colors ${
                    isActive ? `${m.bg} ${m.color}` : 'text-text-muted hover:text-text hover:bg-surface-2'
                  }`}
                >
                  <m.icon className="w-2.5 h-2.5" />
                  {m.label}
                </button>
              )
            })}
          </div>
        </div>

        {/* Create dialog */}
        {createMode && (
          <CreateDialog
            mode={createMode}
            onSubmit={handleCreate}
            onCancel={() => setCreateMode(null)}
          />
        )}

        {/* File tree */}
        <div className="flex-1 overflow-y-auto py-1.5 px-1.5 space-y-0.5">
          {treeLoading ? (
            <div className="flex items-center justify-center py-12">
              <div className="w-5 h-5 border-2 border-accent border-t-transparent rounded-full animate-spin" />
            </div>
          ) : tree.length === 0 ? (
            <div className="px-3 py-8 text-center">
              <Brain className="w-8 h-8 text-text-muted mx-auto mb-2 opacity-50" />
              <p className="text-[12px] text-text-muted">No memory files found</p>
            </div>
          ) : (
            tree.map((node) => (
              <TreeNode
                key={node.path}
                node={node}
                selectedPath={selectedPath}
                onSelect={handleSelectFile}
                onDelete={handleDelete}
                onRename={(p, isDir) => setRenamingPath({ path: p, isDir })}
                depth={0}
                typeFilter={typeFilter}
                searchQuery={!searchResults ? searchQuery : ''}
              />
            ))
          )}
        </div>

        {/* Bottom stats bar */}
        {stats && (
          <div className="px-3 py-2 border-t border-border shrink-0 flex items-center justify-between text-[10px] text-text-muted">
            <span>
              {stats.totalFiles} files / {stats.totalFolders} folders
            </span>
            <span>{formatBytes(stats.totalSize)}</span>
          </div>
        )}
      </aside>

      {/* ═══ Middle Panel — Editor ═══ */}
      <main className="flex-1 min-w-0 flex flex-col h-full bg-surface">
        {/* Editor header */}
        <div className="px-4 py-2.5 border-b border-border flex items-center justify-between shrink-0">
          <div className="flex items-center gap-1.5 text-[12px] text-text-muted min-w-0">
            {breadcrumbs.length === 0 ? (
              <span className="text-text-muted italic">No file selected</span>
            ) : (
              breadcrumbs.map((crumb, i) => (
                <span key={i} className="flex items-center gap-1.5">
                  {i > 0 && <ChevronRight className="w-3 h-3 shrink-0 text-border" />}
                  <span
                    className={
                      i === breadcrumbs.length - 1
                        ? 'text-text font-medium'
                        : 'text-text-muted hover:text-text-secondary cursor-default'
                    }
                  >
                    {crumb}
                  </span>
                </span>
              ))
            )}
            {selectedNode?.frontmatter?.type && (
              <>
                <span className="text-border mx-1">|</span>
                {(() => {
                  const m = TYPE_META[selectedNode.frontmatter.type as MemoryType]
                  return m ? (
                    <span
                      className={`flex items-center gap-1 text-[10px] font-medium px-1.5 py-0.5 rounded-md ${m.bg} ${m.color}`}
                    >
                      <m.icon className="w-2.5 h-2.5" />
                      {m.label}
                    </span>
                  ) : null
                })()}
              </>
            )}
          </div>
          <div className="flex items-center gap-2 shrink-0 ml-4">
            {dirty && (
              <span className="w-2 h-2 rounded-full bg-accent shrink-0 animate-pulse" title="Unsaved changes" />
            )}
            <button
              onClick={handleSave}
              disabled={!dirty || saving}
              className="flex items-center gap-1.5 px-3 py-1.5 text-[12px] font-medium bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
            >
              <Save className="w-3.5 h-3.5" />
              {saving ? 'Saving...' : 'Save'}
            </button>
            <kbd className="text-[10px] text-text-muted bg-surface-2 px-1.5 py-0.5 rounded border border-border hidden sm:block">
              Cmd+S
            </kbd>
          </div>
        </div>

        {/* Editor body */}
        <div className="flex-1 min-h-0 p-3">
          {!selectedPath ? (
            <div className="flex items-center justify-center h-full">
              <div className="text-center space-y-3 max-w-xs">
                <Brain className="w-12 h-12 text-text-muted mx-auto opacity-40" />
                <p className="text-text-secondary text-[15px] font-medium">Select a memory file</p>
                <p className="text-text-muted text-[12px] leading-relaxed">
                  Browse the file tree on the left, or use search (Cmd+K) to find memories across
                  all folders.
                </p>
                <div className="flex flex-wrap gap-2 justify-center pt-2">
                  {MEMORY_TYPES.map((type) => {
                    const m = TYPE_META[type]
                    return (
                      <button
                        key={type}
                        onClick={() => setTypeFilter(type)}
                        className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-[11px] font-medium ${m.bg} ${m.color} hover:opacity-80 transition-opacity`}
                      >
                        <m.icon className="w-3 h-3" />
                        {m.label}
                      </button>
                    )
                  })}
                </div>
              </div>
            </div>
          ) : fileLoading ? (
            <div className="flex items-center justify-center h-full">
              <div className="w-6 h-6 border-2 border-accent border-t-transparent rounded-full animate-spin" />
            </div>
          ) : (
            <textarea
              value={content}
              onChange={(e) => setContent(e.target.value)}
              className="w-full h-full bg-surface border border-border rounded-xl p-4 font-mono text-[13px] text-text resize-none focus:outline-none focus:border-accent/50 transition-colors leading-relaxed"
              spellCheck={false}
              placeholder="Start writing..."
            />
          )}
        </div>
      </main>

      {/* ═══ Right Panel — Info / Stats ═══ */}
      <aside className="w-[260px] min-w-[260px] border-l border-border bg-surface flex flex-col h-full">
        {/* Panel tabs */}
        <div className="px-3 py-2 border-b border-border shrink-0 flex items-center gap-1">
          <button
            onClick={() => setRightPanel('info')}
            className={`flex items-center gap-1.5 px-3 py-1.5 text-[12px] font-medium rounded-lg transition-colors ${
              rightPanel === 'info'
                ? 'bg-accent-muted text-accent'
                : 'text-text-muted hover:text-text hover:bg-surface-2'
            }`}
          >
            <Tag className="w-3.5 h-3.5" />
            Info
          </button>
          <button
            onClick={() => setRightPanel('stats')}
            className={`flex items-center gap-1.5 px-3 py-1.5 text-[12px] font-medium rounded-lg transition-colors ${
              rightPanel === 'stats'
                ? 'bg-accent-muted text-accent'
                : 'text-text-muted hover:text-text hover:bg-surface-2'
            }`}
          >
            <BarChart3 className="w-3.5 h-3.5" />
            Stats
          </button>
        </div>

        {/* Panel content */}
        <div className="flex-1 overflow-y-auto p-3">
          {rightPanel === 'stats' ? (
            <StatsPanel stats={stats} />
          ) : (
            <InfoSidebar filePath={selectedPath} content={content} node={selectedNode} />
          )}
        </div>
      </aside>

      {/* ═══ Rename Dialog ═══ */}
      {renamingPath && (
        <RenameDialog
          currentPath={renamingPath.path}
          isDir={renamingPath.isDir}
          onSubmit={handleRename}
          onCancel={() => setRenamingPath(null)}
        />
      )}
    </div>
  )
}

