              <div>
                <p className="text-[10px] text-text-muted">Priority</p>
                <span
                  className={`inline-block text-[11px] px-2 py-0.5 rounded-md font-medium capitalize ${PRIORITY_COLORS[meta.priority] || 'text-text-secondary bg-surface-3'}`}
