1231	function buildMemoryTree(dir, base) {
1232	  const entries = fs.readdirSync(dir, { withFileTypes: true });
1233	  const dirs = [];
1234	  const files = [];
1235	
1236	  for (const entry of entries) {
1237	    if (entry.name.startsWith('.') || entry.name === '.DS_Store') continue;
1238	    const entryPath = base ? `${base}/${entry.name}` : entry.name;
1239	    if (entry.isDirectory()) {
1240	      dirs.push({
1241	        type: 'dir',
1242	        name: entry.name,
1243	        path: entryPath,
1244	        children: buildMemoryTree(path.join(dir, entry.name), entryPath),
1245	      });
1246	    } else {
1247	      const absPath = path.join(dir, entry.name);
1248	      const stat = fs.statSync(absPath);
1249	      const node = { type: 'file', name: entry.name, path: entryPath, size: stat.size, modifiedAt: stat.mtime.toISOString() };
1250	      // Parse frontmatter for .md files
1251	      if (entry.name.endsWith('.md')) {
1252	        try {
1253	          const raw = fs.readFileSync(absPath, 'utf-8');
1254	          const fmMatch = raw.match(/^---\r?\n([\s\S]*?)\r?\n---/);
1255	          if (fmMatch) {
1256	            const fm = {};
1257	            for (const line of fmMatch[1].split('\n')) {
