1259	              if (kv) fm[kv[1]] = kv[2].trim();
1260	            }
1261	            node.frontmatter = fm;
1262	          }
1263	        } catch {}
1264	      }
1265	      files.push(node);
1266	    }
1267	  }
1268	
1269	  dirs.sort((a, b) => a.name.localeCompare(b.name));
1270	  files.sort((a, b) => a.name.localeCompare(b.name));
1271	  return [...dirs, ...files];
1272	}
