// --- Memory Brain Endpoints ---

const MEMORY_DIR = path.join(CLAUDE_DIR, 'memory');

// ── Audit Log System ──────────────────────────────────────────────────────────
// Every mutation (create, update, delete, rename/move) is recorded with a
// line-level diff so the user can see exactly what changed and when.

function computeLineDiff(before, after) {
  const oldLines = (before || '').split('\n');
  const newLines = (after || '').split('\n');
  const hunks = [];
  const maxLen = Math.max(oldLines.length, newLines.length);
  let i = 0;
  while (i < maxLen) {
    // Skip identical lines
    if (i < oldLines.length && i < newLines.length && oldLines[i] === newLines[i]) { i++; continue; }
    // Start of a changed region
    const hunkStart = i;
    const removed = [];
    const added = [];
    // Collect contiguous changed lines (simple sequential diff)
    while (i < maxLen && !(i < oldLines.length && i < newLines.length && oldLines[i] === newLines[i])) {
      if (i < oldLines.length && (i >= newLines.length || oldLines[i] !== newLines[i])) {
        removed.push(oldLines[i]);
      }
      if (i < newLines.length && (i >= oldLines.length || oldLines[i] !== newLines[i])) {
        added.push(newLines[i]);
      }
      i++;
    }
    if (removed.length || added.length) {
      hunks.push({ line: hunkStart + 1, removed, added });
    }
  }
  return hunks;
}

function loadAuditLog() {
  try {
    if (fs.existsSync(MEMORY_LOG_PATH)) {
      return JSON.parse(fs.readFileSync(MEMORY_LOG_PATH, 'utf-8'));
    }
  } catch {}
  return [];
}

function saveAuditLog(entries) {
  // Keep last 5000 entries max to prevent unbounded growth
  const trimmed = entries.slice(-5000);
  fs.writeFileSync(MEMORY_LOG_PATH, JSON.stringify(trimmed, null, 2), 'utf-8');
}

function logMemoryAction(action, filePath, { before, after, fromPath, toPath } = {}) {
  const entries = loadAuditLog();
  const entry = {
    id: Date.now().toString(36) + Math.random().toString(36).slice(2, 8),
    timestamp: new Date().toISOString(),
    action, // 'create' | 'update' | 'delete' | 'move' | 'create_folder' | 'delete_folder'
    path: filePath,
    linesAdded: 0,
    linesRemoved: 0,
  };
  if (action === 'update' && before !== undefined && after !== undefined) {
    const diff = computeLineDiff(before, after);
    entry.diff = diff;
    entry.linesAdded = diff.reduce((s, h) => s + h.added.length, 0);
    entry.linesRemoved = diff.reduce((s, h) => s + h.removed.length, 0);
    entry.sizeBefore = (before || '').length;
    entry.sizeAfter = (after || '').length;
  }
  if (action === 'create' && after !== undefined) {
    const lines = after.split('\n').length;
    entry.linesAdded = lines;
    entry.sizeAfter = after.length;
  }
  if (action === 'delete' && before !== undefined) {
    const lines = before.split('\n').length;
    entry.linesRemoved = lines;
    entry.sizeBefore = before.length;
    entry.contentSnapshot = before; // keep last version for recovery
  }
  if (action === 'move') {
    entry.fromPath = fromPath;
    entry.toPath = toPath;
  }
  // Parse frontmatter for context
  const content = after || before || '';
  const fmMatch = content.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (fmMatch) {
    const fm = {};
    for (const line of fmMatch[1].split('\n')) {
      const kv = line.match(/^([\w-]+):\s*(.*)$/);
      if (kv) fm[kv[1]] = kv[2].trim();
    }
    entry.frontmatter = fm;
  }
  entries.push(entry);
  saveAuditLog(entries);
}

function resolveMemoryPath(relPath) {
  if (!relPath || typeof relPath !== 'string') return null;
  const resolved = path.resolve(MEMORY_DIR, relPath);
  if (!resolved.startsWith(MEMORY_DIR + path.sep) && resolved !== MEMORY_DIR) return null;
  return resolved;
}

function buildMemoryTree(dir, base) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  const dirs = [];
  const files = [];

  for (const entry of entries) {
    if (entry.name.startsWith('.') || entry.name === '.DS_Store') continue;
    const entryPath = base ? `${base}/${entry.name}` : entry.name;
    if (entry.isDirectory()) {
      dirs.push({
        type: 'dir',
        name: entry.name,
        path: entryPath,
        children: buildMemoryTree(path.join(dir, entry.name), entryPath),
      });
    } else {
      const absPath = path.join(dir, entry.name);
      const stat = fs.statSync(absPath);
      const node = { type: 'file', name: entry.name, path: entryPath, size: stat.size, modifiedAt: stat.mtime.toISOString() };
      // Parse frontmatter for .md files
      if (entry.name.endsWith('.md')) {
        try {
          const raw = fs.readFileSync(absPath, 'utf-8');
          const fmMatch = raw.match(/^---\r?\n([\s\S]*?)\r?\n---/);
          if (fmMatch) {
            const fm = {};
            for (const line of fmMatch[1].split('\n')) {
              const kv = line.match(/^(\w[\w-]*):\s*(.*)$/);
              if (kv) fm[kv[1]] = kv[2].trim();
            }
            node.frontmatter = fm;
          }
        } catch {}
      }
      files.push(node);
    }
  }

  dirs.sort((a, b) => a.name.localeCompare(b.name));
  files.sort((a, b) => a.name.localeCompare(b.name));
  return [...dirs, ...files];
}

// Collect all files from tree recursively (flat list)
function flattenTree(nodes) {
  const result = [];
  for (const node of nodes) {
    if (node.type === 'file') result.push(node);
    if (node.type === 'dir' && node.children) result.push(...flattenTree(node.children));
  }
  return result;
}

app.get('/api/memory', (req, res) => {
  try {
    ensureDir(MEMORY_DIR);
    const tree = buildMemoryTree(MEMORY_DIR, '');
    res.json(tree);
  } catch (err) {
    res.status(500).json({ error: 'Failed to read memory directory' });
  }
});

app.get('/api/memory/file', (req, res) => {
  const relPath = req.query.path;
  const absPath = resolveMemoryPath(relPath);
  if (!absPath) return res.status(400).json({ error: 'Invalid path' });
  if (!fs.existsSync(absPath)) return res.status(404).json({ error: 'File not found' });
  try {
    const content = fs.readFileSync(absPath, 'utf-8');
    res.json({ path: relPath, content });
  } catch {
    res.status(500).json({ error: 'Failed to read file' });
  }
});

app.put('/api/memory/file', (req, res) => {
  const { path: relPath, content } = req.body;
  const absPath = resolveMemoryPath(relPath);
  if (!absPath) return res.status(400).json({ error: 'Invalid path' });
  if (typeof content !== 'string') return res.status(400).json({ error: 'content must be a string' });
  try {
    const before = fs.existsSync(absPath) ? fs.readFileSync(absPath, 'utf-8') : '';
    ensureDir(path.dirname(absPath));
    fs.writeFileSync(absPath, content, 'utf-8');
    if (before !== content) {
      logMemoryAction('update', relPath, { before, after: content });
    }
    res.json({ ok: true });
  } catch {
    res.status(500).json({ error: 'Failed to write file' });
  }
});

app.post('/api/memory/file', (req, res) => {
  const { path: relPath } = req.body;
  const absPath = resolveMemoryPath(relPath);
  if (!absPath) return res.status(400).json({ error: 'Invalid path' });
  if (fs.existsSync(absPath)) return res.status(409).json({ error: 'File already exists' });
  try {
    ensureDir(path.dirname(absPath));
    const isMd = absPath.endsWith('.md');
    const defaultContent = isMd
      ? `---\ntype: reference\n---\n\n# ${path.basename(absPath, '.md')}\n\n`
      : '';
    fs.writeFileSync(absPath, defaultContent, 'utf-8');
    logMemoryAction('create', relPath, { after: defaultContent });
    res.json({ ok: true });
  } catch {
    res.status(500).json({ error: 'Failed to create file' });
  }
});

app.delete('/api/memory/file', (req, res) => {
  const relPath = req.query.path;
  const absPath = resolveMemoryPath(relPath);
  if (!absPath) return res.status(400).json({ error: 'Invalid path' });
  if (!fs.existsSync(absPath)) return res.status(404).json({ error: 'File not found' });
  try {
    const before = fs.readFileSync(absPath, 'utf-8');
    fs.unlinkSync(absPath);
    logMemoryAction('delete', relPath, { before });
    res.json({ ok: true });
  } catch {
    res.status(500).json({ error: 'Failed to delete file' });
  }
});

// Search across all memory files
app.get('/api/memory/search', (req, res) => {
  const query = (req.query.q || '').toLowerCase().trim();
  if (!query) return res.json([]);
  try {
    ensureDir(MEMORY_DIR);
    const tree = buildMemoryTree(MEMORY_DIR, '');
    const allFiles = flattenTree(tree);
    const results = [];
    for (const file of allFiles) {
      const absPath = path.resolve(MEMORY_DIR, file.path);
      let content = '';
      try { content = fs.readFileSync(absPath, 'utf-8'); } catch { continue; }
      const nameMatch = file.name.toLowerCase().includes(query);
      const pathMatch = file.path.toLowerCase().includes(query);
      const fmName = file.frontmatter?.name?.toLowerCase() || '';
      const fmDesc = file.frontmatter?.description?.toLowerCase() || '';
      const fmType = file.frontmatter?.type?.toLowerCase() || '';
      const fmMatch = fmName.includes(query) || fmDesc.includes(query) || fmType.includes(query);
      const contentLower = content.toLowerCase();
      const contentMatch = contentLower.includes(query);
      if (nameMatch || pathMatch || fmMatch || contentMatch) {
        let snippet = '';
        if (contentMatch) {
          const idx = contentLower.indexOf(query);
          const start = Math.max(0, idx - 60);
          const end = Math.min(content.length, idx + query.length + 60);
          snippet = (start > 0 ? '...' : '') + content.slice(start, end).replace(/\n/g, ' ') + (end < content.length ? '...' : '');
        }
        results.push({
          path: file.path,
          name: file.name,
          frontmatter: file.frontmatter || {},
          snippet,
          matchType: nameMatch ? 'name' : fmMatch ? 'frontmatter' : pathMatch ? 'path' : 'content',
        });
      }
    }
    res.json(results);
  } catch (err) {
    res.status(500).json({ error: 'Search failed' });
  }
});

// Stats for the memory brain
app.get('/api/memory/stats', (req, res) => {
  try {
    ensureDir(MEMORY_DIR);
    const tree = buildMemoryTree(MEMORY_DIR, '');
    const allFiles = flattenTree(tree);
    const totalFiles = allFiles.length;
    let totalSize = 0;
    const typeCount = {};
    const folderCount = {};
    for (const file of allFiles) {
      totalSize += file.size || 0;
      const fmType = file.frontmatter?.type || 'unknown';
      typeCount[fmType] = (typeCount[fmType] || 0) + 1;
      const folder = file.path.includes('/') ? file.path.split('/')[0] : 'root';
      folderCount[folder] = (folderCount[folder] || 0) + 1;
    }
    // Count dirs
    function countDirs(nodes) {
      let count = 0;
      for (const n of nodes) {
        if (n.type === 'dir') { count++; if (n.children) count += countDirs(n.children); }
      }
      return count;
    }
    res.json({ totalFiles, totalSize, totalFolders: countDirs(tree), typeCount, folderCount });
  } catch {
    res.status(500).json({ error: 'Failed to compute stats' });
  }
});

// Create folder
app.post('/api/memory/folder', (req, res) => {
  const { path: relPath } = req.body;
  const absPath = resolveMemoryPath(relPath);
  if (!absPath) return res.status(400).json({ error: 'Invalid path' });
  if (fs.existsSync(absPath)) return res.status(409).json({ error: 'Folder already exists' });
  try {
    fs.mkdirSync(absPath, { recursive: true });
    logMemoryAction('create_folder', relPath);
    res.json({ ok: true });
  } catch {
    res.status(500).json({ error: 'Failed to create folder' });
  }
});

// Delete folder (must be empty)
app.delete('/api/memory/folder', (req, res) => {
  const relPath = req.query.path;
  const absPath = resolveMemoryPath(relPath);
  if (!absPath) return res.status(400).json({ error: 'Invalid path' });
  if (!fs.existsSync(absPath)) return res.status(404).json({ error: 'Folder not found' });
  try {
    const entries = fs.readdirSync(absPath).filter(e => e !== '.DS_Store');
    if (entries.length > 0) return res.status(400).json({ error: 'Folder is not empty' });
    fs.rmSync(absPath, { recursive: true });
    logMemoryAction('delete_folder', relPath);
    res.json({ ok: true });
  } catch {
    res.status(500).json({ error: 'Failed to delete folder' });
  }
});

// Rename / move file
app.post('/api/memory/move', (req, res) => {
  const { from, to } = req.body;
  const absFrom = resolveMemoryPath(from);
  const absTo = resolveMemoryPath(to);
  if (!absFrom || !absTo) return res.status(400).json({ error: 'Invalid path' });
  if (!fs.existsSync(absFrom)) return res.status(404).json({ error: 'Source not found' });
  if (fs.existsSync(absTo)) return res.status(409).json({ error: 'Destination already exists' });
  try {
    ensureDir(path.dirname(absTo));
    fs.renameSync(absFrom, absTo);
    logMemoryAction('move', to, { fromPath: from, toPath: to });
    res.json({ ok: true });
  } catch {
    res.status(500).json({ error: 'Failed to move file' });
  }
});

// --- Setup / Health Endpoints ---

const { execSync } = require('child_process');

app.get('/api/setup/status', (req, res) => {
  // 1. pm2 status
  let pm2Status = 'unknown';
  try {
    const out = execSync('pm2 jlist 2>/dev/null', { encoding: 'utf-8', timeout: 5000 });
    const list = JSON.parse(out);
    const hub = list.find(p => p.name === 'claude-hub');
    pm2Status = hub ? hub.pm2_env.status : 'not_registered';
  } catch {
    pm2Status = 'not_installed';
  }

  // 2. LaunchAgent
  const launchAgentPath = path.join(os.homedir(), 'Library/LaunchAgents/io.boldteq.claude-hub.plist');
  const launchAgentInstalled = fs.existsSync(launchAgentPath);

  // 3. Agent count
  const agentDir = path.join(CLAUDE_DIR, 'agents');
  const agentCount = fs.existsSync(agentDir)
    ? fs.readdirSync(agentDir).filter(f => f.endsWith('.md')).length
    : 0;

  // 4. SDK location
  const sdkPath = path.join(__dirname, '..', 'sdk');
  const sdkExists = fs.existsSync(path.join(sdkPath, 'package.json'));

  res.json({ pm2Status, launchAgentInstalled, agentCount, sdkExists, port: process.env.PORT || 3847 });
});

app.get('/api/setup/projects', (req, res) => {
  const config = loadConfig();
  const results = [];

  for (const dir of config.projectDirs || []) {
    const resolved = dir.replace(/^~/, HOME);
    if (!fs.existsSync(resolved)) continue;
    try {
      const entries = fs.readdirSync(resolved, { withFileTypes: true });
      for (const entry of entries) {
        if (!entry.isDirectory()) continue;
        if (entry.name.startsWith('.') || entry.name === 'node_modules') continue;
        const projectPath = path.join(resolved, entry.name);
        const hasPackageJson = fs.existsSync(path.join(projectPath, 'package.json'));
        const hasClaudeDir = fs.existsSync(path.join(projectPath, '.claude'));
        const hasClaudeMd = fs.existsSync(path.join(projectPath, 'CLAUDE.md'));
        const hasPubspec = fs.existsSync(path.join(projectPath, 'pubspec.yaml'));
        if (!hasClaudeDir && !hasClaudeMd && !hasPackageJson && !hasPubspec) continue;

        const hasSdk = fs.existsSync(path.join(projectPath, 'node_modules', '@boldteq', 'agents'));
        let hasPackageEntry = false;
        if (hasPackageJson) {
          try {
            const pkg = JSON.parse(fs.readFileSync(path.join(projectPath, 'package.json'), 'utf-8'));
            hasPackageEntry = !!(
              (pkg.dependencies && pkg.dependencies['@boldteq/agents']) ||
              (pkg.devDependencies && pkg.devDependencies['@boldteq/agents'])
            );
          } catch {}
        }

        results.push({
          name: entry.name,
          path: projectPath,
          hasSdk,
          hasPackageEntry,
        });
      }
    } catch {}
  }

  res.json(results);
});

app.post('/api/setup/install-sdk', (req, res) => {
  const { projectPath } = req.body;
  if (!projectPath || typeof projectPath !== 'string') {
    return res.status(400).json({ error: 'projectPath is required' });
  }

  // Validate path exists
  const resolvedProject = path.resolve(projectPath);
  if (!fs.existsSync(resolvedProject) || !fs.statSync(resolvedProject).isDirectory()) {
    return res.status(400).json({ error: 'Project path does not exist' });
  }

  // Validate it's within a known project dir
  const config = loadConfig();
  const allowedRoots = (config.projectDirs || []).map(d => path.resolve(d.replace(/^~/, HOME)));
  const isAllowed = allowedRoots.some(root => resolvedProject.startsWith(root));
  if (!isAllowed) {
    return res.status(403).json({ error: 'Path outside allowed project directories' });
  }

  // Read or create package.json
  const pkgPath = path.join(resolvedProject, 'package.json');
  let pkg = { name: path.basename(resolvedProject), version: '1.0.0', dependencies: {} };
  if (fs.existsSync(pkgPath)) {
    try {
      pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf-8'));
    } catch {
      return res.status(500).json({ error: 'Could not parse project package.json' });
    }
  }

  // Calculate relative path from project to sdk
  const sdkAbsPath = path.resolve(path.join(__dirname, '..', 'sdk'));
  const relPath = path.relative(resolvedProject, sdkAbsPath);

  // Add dependency
  if (!pkg.dependencies) pkg.dependencies = {};
  pkg.dependencies['@boldteq/agents'] = `file:${relPath}`;
  fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2));

  // Run npm install
  try {
    execSync('npm install', { cwd: resolvedProject, timeout: 60000, stdio: 'pipe' });
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: err.message || 'npm install failed' });
  }
});

// ─── Docs ────────────────────────────────────────────────────────────────────
const DOCS_PATH = path.join(__dirname, '..', 'docs');

app.get('/api/docs', (req, res) => {
  if (!fs.existsSync(DOCS_PATH)) return res.json([]);
  const files = fs.readdirSync(DOCS_PATH).filter(f => f.endsWith('.md')).sort();
  const docs = files.map(f => {
    const raw = fs.readFileSync(path.join(DOCS_PATH, f), 'utf-8');
    const firstHeading = raw.split('\n').find(l => l.startsWith('# ')) || '';
    const title = firstHeading.replace(/^# /, '') || f.replace('.md', '');
    // Pull first non-blank, non-heading line as description
    const desc = raw.split('\n').find(l => l.trim() && !l.startsWith('#')) || '';
    return { slug: f.replace('.md', ''), filename: f, title, description: desc.trim() };
  });
  res.json(docs);
});

app.get('/api/docs/:slug', (req, res) => {
  const slug = req.params.slug.replace(/[^a-zA-Z0-9-_]/g, '');
  const filePath = path.join(DOCS_PATH, `${slug}.md`);
  if (!fs.existsSync(filePath)) return res.status(404).json({ error: 'Not found' });
  res.json({ slug, content: fs.readFileSync(filePath, 'utf-8') });
});

// SPA fallback
app.get('*', (req, res) => {
  res.sendFile(path.join(staticPath, 'index.html'));
});

const PORT = process.env.PORT || 3847;
app.listen(PORT, () => {
  console.log('');
  console.log('  ╔══════════════════════════════════════╗');
  console.log('  ║         Claude Hub is running         ║');
  console.log(`  ║     http://localhost:${PORT}            ║`);
  console.log('  ╚══════════════════════════════════════╝');
  console.log('');
  console.log(`  Claude dir: ${CLAUDE_DIR}`);
  console.log(`  Config: ${CONFIG_PATH}`);
  console.log('');
});

