#!/usr/bin/env node
/**
 * Auto-Screenshot Utility for Visual Validation
 *
 * Usage:
 *   node scripts/screenshot.mjs                          # Desktop screenshots of all auto-detected routes
 *   node scripts/screenshot.mjs --viewport all           # All viewports (mobile, tablet, desktop)
 *   node scripts/screenshot.mjs --routes /,/settings     # Specific routes only
 *   node scripts/screenshot.mjs --dark                   # Dark mode
 *   node scripts/screenshot.mjs --full-page              # Full page scroll capture
 *   node scripts/screenshot.mjs --port 3000              # Override port
 *
 * Output: .screenshots/ directory with PNG files + manifest.json
 */

import { chromium } from 'playwright';
import { mkdirSync, existsSync, readFileSync, writeFileSync, readdirSync } from 'fs';
import { join, resolve } from 'path';

// --- Config ---
const SCREENSHOT_DIR = resolve('.screenshots');
const VIEWPORTS = {
  mobile:  { width: 375, height: 812 },
  tablet:  { width: 768, height: 1024 },
  desktop: { width: 1440, height: 900 },
};

// --- Helpers ---
function detectPort() {
  const files = [
    { path: 'vite.config.ts', regex: /port:\s*(\d+)/ },
    { path: 'vite.config.js', regex: /port:\s*(\d+)/ },
    { path: 'next.config.js', regex: /port:\s*(\d+)/ },
    { path: 'next.config.mjs', regex: /port:\s*(\d+)/ },
  ];
  for (const f of files) {
    if (existsSync(f.path)) {
      const content = readFileSync(f.path, 'utf-8');
      const match = content.match(f.regex);
      if (match) return parseInt(match[1]);
    }
  }
  if (existsSync('package.json')) {
    const pkg = JSON.parse(readFileSync('package.json', 'utf-8'));
    const devScript = pkg.scripts?.dev || '';
    const portMatch = devScript.match(/--port\s+(\d+)/);
    if (portMatch) return parseInt(portMatch[1]);
  }
  if (existsSync('vite.config.ts') || existsSync('vite.config.js')) return 8080;
  return 3000;
}

function detectRoutes() {
  const routes = new Set(['/']);

  // React Router: parse path="..." from App.tsx
  const routeFiles = ['src/App.tsx', 'src/app/App.tsx', 'app/routes.tsx'];
  for (const file of routeFiles) {
    if (!existsSync(file)) continue;
    const content = readFileSync(file, 'utf-8');
    const pathMatches = content.matchAll(/path=["']([^"']+)["']/g);
    for (const m of pathMatches) {
      const route = m[1];
      if (!route.includes(':') && !route.includes('*') && !route.includes('$')) {
        routes.add(route.startsWith('/') ? route : '/' + route);
      }
    }
  }

  // Lovable/Vite: scan src/pages/ directory
  if (existsSync('src/pages')) {
    try {
      const pages = readdirSync('src/pages').filter(f => f.endsWith('.tsx') && f !== 'NotFound.tsx');
      for (const page of pages) {
        const name = page.replace('.tsx', '');
        if (name === 'Index') {
          routes.add('/');
        } else {
          // PascalCase → lowercase route
          const route = '/' + name.charAt(0).toLowerCase() + name.slice(1);
          routes.add(route);
        }
      }
    } catch (e) { /* ignore */ }
  }

  // Next.js App Router: scan app/ for page.tsx files
  if (existsSync('app') || existsSync('src/app')) {
    const appDir = existsSync('src/app') ? 'src/app' : 'app';
    function scanDir(dir, prefix) {
      try {
        const entries = readdirSync(dir, { withFileTypes: true });
        for (const entry of entries) {
          if (entry.isDirectory() && !entry.name.startsWith('_') && !entry.name.startsWith('(')) {
            scanDir(join(dir, entry.name), prefix + '/' + entry.name);
          }
          if (entry.name === 'page.tsx' || entry.name === 'page.jsx') {
            routes.add(prefix || '/');
          }
        }
      } catch (e) { /* ignore */ }
    }
    scanDir(appDir, '');
  }

  return [...routes].sort();
}

function parseArgs() {
  const args = process.argv.slice(2);
  const parsed = {};
  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--port') parsed.port = parseInt(args[++i]);
    if (args[i] === '--routes') parsed.routes = args[++i].split(',');
    if (args[i] === '--viewport') parsed.viewport = args[++i];
    if (args[i] === '--dark') parsed.dark = true;
    if (args[i] === '--full-page') parsed.fullPage = true;
    if (args[i] === '--help') {
      console.log(`
Usage: node scripts/screenshot.mjs [options]

Options:
  --port <number>     Override dev server port (auto-detected by default)
  --routes <list>     Comma-separated routes (auto-detected by default)
  --viewport <type>   mobile | tablet | desktop | all (default: desktop)
  --dark              Use dark color scheme
  --full-page         Capture full scrollable page
  --help              Show this help
      `);
      process.exit(0);
    }
  }
  return parsed;
}

// --- Main ---
async function run() {
  const args = parseArgs();
  const port = args.port || detectPort();
  const baseUrl = `http://localhost:${port}`;
  const routes = args.routes || detectRoutes();
  const viewportKeys = args.viewport === 'all'
    ? Object.keys(VIEWPORTS)
    : [args.viewport || 'desktop'];

  // Check if server is running
  try {
    const res = await fetch(baseUrl, { signal: AbortSignal.timeout(3000) });
  } catch {
    console.error(`\n  Dev server not running at ${baseUrl}`);
    console.error(`  Start it first: npm run dev\n`);
    process.exit(1);
  }

  console.log(`\n  Screenshot config:`);
  console.log(`  Base URL:  ${baseUrl}`);
  console.log(`  Routes:    ${routes.join(', ')}`);
  console.log(`  Viewports: ${viewportKeys.join(', ')}`);
  console.log(`  Dark mode: ${args.dark ? 'yes' : 'no'}`);
  console.log(`  Output:    ${SCREENSHOT_DIR}/\n`);

  mkdirSync(SCREENSHOT_DIR, { recursive: true });

  const browser = await chromium.launch({ headless: true });
  const results = [];

  for (const vpKey of viewportKeys) {
    const vp = VIEWPORTS[vpKey];
    const context = await browser.newContext({
      viewport: vp,
      deviceScaleFactor: 2,
      colorScheme: args.dark ? 'dark' : 'light',
    });

    const page = await context.newPage();
    const consoleErrors = [];
    page.on('console', msg => {
      if (msg.type() === 'error') consoleErrors.push(msg.text());
    });

    for (const route of routes) {
      const url = `${baseUrl}${route}`;
      const safeName = route.replace(/\//g, '_').replace(/^_/, '') || 'home';
      const darkSuffix = args.dark ? '_dark' : '';
      const filename = `${vpKey}_${safeName}${darkSuffix}.png`;
      const filepath = join(SCREENSHOT_DIR, filename);

      try {
        const response = await page.goto(url, {
          waitUntil: 'networkidle',
          timeout: 15000,
        });

        // Wait for hydration + lazy content
        await page.waitForTimeout(2000);

        await page.screenshot({
          path: filepath,
          fullPage: args.fullPage || false,
        });

        const status = response?.status() || 'unknown';
        results.push({
          route,
          viewport: vpKey,
          file: filename,
          status,
          consoleErrors: [...consoleErrors],
        });

        console.log(`  OK  ${vpKey.padEnd(7)} ${route.padEnd(20)} -> ${filename} (${status})`);
        consoleErrors.length = 0;
      } catch (err) {
        results.push({
          route,
          viewport: vpKey,
          file: null,
          status: 'FAILED',
          error: err.message,
        });
        console.log(`  ERR ${vpKey.padEnd(7)} ${route.padEnd(20)} -> FAILED: ${err.message}`);
      }
    }

    await context.close();
  }

  await browser.close();

  // Write manifest
  const manifest = {
    timestamp: new Date().toISOString(),
    baseUrl,
    port,
    routes,
    viewports: viewportKeys,
    darkMode: args.dark || false,
    fullPage: args.fullPage || false,
    screenshots: results,
    summary: {
      total: results.length,
      success: results.filter(r => r.file).length,
      failed: results.filter(r => !r.file).length,
      withErrors: results.filter(r => r.consoleErrors?.length > 0).length,
    },
  };
  writeFileSync(join(SCREENSHOT_DIR, 'manifest.json'), JSON.stringify(manifest, null, 2));

  // Print summary
  console.log(`\n  Summary:`);
  console.log(`  ${manifest.summary.success} captured, ${manifest.summary.failed} failed, ${manifest.summary.withErrors} with console errors`);
  console.log(`  Manifest: .screenshots/manifest.json\n`);

  if (manifest.summary.failed > 0) {
    console.log(`  Failed routes:`);
    results.filter(r => !r.file).forEach(f =>
      console.log(`    ${f.route}: ${f.error}`)
    );
    console.log('');
  }

  if (manifest.summary.withErrors > 0) {
    console.log(`  Routes with console errors:`);
    results.filter(r => r.consoleErrors?.length > 0).forEach(r => {
      console.log(`    ${r.route}:`);
      r.consoleErrors.forEach(e => console.log(`      ${e}`));
    });
    console.log('');
  }
}

run().catch(err => {
  console.error('Screenshot script failed:', err.message);
  process.exit(1);
});

