  const { path: relPath, content } = req.body;
  const absPath = resolveMemoryPath(relPath);
  if (!absPath) return res.status(400).json({ error: 'Invalid path' });
  if (typeof content !== 'string') return res.status(400).json({ error: 'content must be a string' });
  try {
    const before = fs.existsSync(absPath) ? fs.readFileSync(absPath, 'utf-8') : '';
    ensureDir(path.dirname(absPath));
    fs.writeFileSync(absPath, content, 'utf-8');
    if (before !== content) {
      logMemoryAction('update', relPath, { before, after: content });
    }
    res.json({ ok: true });
  } catch {
    res.status(500).json({ error: 'Failed to write file' });
  }
});

app.post('/api/memory/file', (req, res) => {
  const { path: relPath } = req.body;
  const absPath = resolveMemoryPath(relPath);
  if (!absPath) return res.status(400).json({ error: 'Invalid path' });
  if (fs.existsSync(absPath)) return res.status(409).json({ error: 'File already exists' });
  try {
    ensureDir(path.dirname(absPath));
    const isMd = absPath.endsWith('.md');
    const defaultContent = isMd
      ? `---\ntype: reference\n---\n\n# ${path.basename(absPath, '.md')}\n\n`
      : '';
    fs.writeFileSync(absPath, defaultContent, 'utf-8');
    logMemoryAction('create', relPath, { after: defaultContent });
    res.json({ ok: true });
  } catch {
    res.status(500).json({ error: 'Failed to create file' });
  }
});

app.delete('/api/memory/file', (req, res) => {
  const relPath = req.query.path;
  const absPath = resolveMemoryPath(relPath);
  if (!absPath) return res.status(400).json({ error: 'Invalid path' });
  if (!fs.existsSync(absPath)) return res.status(404).json({ error: 'File not found' });
  try {
    const before = fs.readFileSync(absPath, 'utf-8');
    fs.unlinkSync(absPath);
    logMemoryAction('delete', relPath, { before });
    res.json({ ok: true });
  } catch {
    res.status(500).json({ error: 'Failed to delete file' });
  }
});

// Search across all memory files
app.get('/api/memory/search', (req, res) => {
  const query = (req.query.q || '').toLowerCase().trim();
  if (!query) return res.json([]);
  try {
    ensureDir(MEMORY_DIR);
    const tree = buildMemoryTree(MEMORY_DIR, '');
    const allFiles = flattenTree(tree);
    const results = [];
    for (const file of allFiles) {
      const absPath = path.resolve(MEMORY_DIR, file.path);
      let content = '';
      try { content = fs.readFileSync(absPath, 'utf-8'); } catch { continue; }
      const nameMatch = file.name.toLowerCase().includes(query);
      const pathMatch = file.path.toLowerCase().includes(query);
      const fmName = file.frontmatter?.name?.toLowerCase() || '';
      const fmDesc = file.frontmatter?.description?.toLowerCase() || '';
      const fmType = file.frontmatter?.type?.toLowerCase() || '';
      const fmMatch = fmName.includes(query) || fmDesc.includes(query) || fmType.includes(query);
      const contentLower = content.toLowerCase();
      const contentMatch = contentLower.includes(query);
      if (nameMatch || pathMatch || fmMatch || contentMatch) {
        let snippet = '';
        if (contentMatch) {
          const idx = contentLower.indexOf(query);
          const start = Math.max(0, idx - 60);
          const end = Math.min(content.length, idx + query.length + 60);
          snippet = (start > 0 ? '...' : '') + content.slice(start, end).replace(/\n/g, ' ') + (end < content.length ? '...' : '');
        }
        results.push({
          path: file.path,
          name: file.name,
          frontmatter: file.frontmatter || {},
          snippet,
          matchType: nameMatch ? 'name' : fmMatch ? 'frontmatter' : pathMatch ? 'path' : 'content',
        });
      }
    }
    res.json(results);
  } catch (err) {
    res.status(500).json({ error: 'Search failed' });
  }
});

// Stats for the memory brain
app.get('/api/memory/stats', (req, res) => {
  try {
    ensureDir(MEMORY_DIR);
    const tree = buildMemoryTree(MEMORY_DIR, '');
    const allFiles = flattenTree(tree);
    const totalFiles = allFiles.length;
    let totalSize = 0;
    const typeCount = {};
    const folderCount = {};
    for (const file of allFiles) {
      totalSize += file.size || 0;
      const fmType = file.frontmatter?.type || 'unknown';
      typeCount[fmType] = (typeCount[fmType] || 0) + 1;
      const folder = file.path.includes('/') ? file.path.split('/')[0] : 'root';
      folderCount[folder] = (folderCount[folder] || 0) + 1;
    }
    // Count dirs
    function countDirs(nodes) {
      let count = 0;
      for (const n of nodes) {
        if (n.type === 'dir') { count++; if (n.children) count += countDirs(n.children); }
      }
      return count;
    }
    res.json({ totalFiles, totalSize, totalFolders: countDirs(tree), typeCount, folderCount });
  } catch {
    res.status(500).json({ error: 'Failed to compute stats' });
  }
});

// Create folder
app.post('/api/memory/folder', (req, res) => {
  const { path: relPath } = req.body;
  const absPath = resolveMemoryPath(relPath);
  if (!absPath) return res.status(400).json({ error: 'Invalid path' });
  if (fs.existsSync(absPath)) return res.status(409).json({ error: 'Folder already exists' });
  try {
    fs.mkdirSync(absPath, { recursive: true });
    logMemoryAction('create_folder', relPath);
    res.json({ ok: true });
  } catch {
    res.status(500).json({ error: 'Failed to create folder' });
  }
});

// Delete folder (must be empty)
app.delete('/api/memory/folder', (req, res) => {
  const relPath = req.query.path;
  const absPath = resolveMemoryPath(relPath);
  if (!absPath) return res.status(400).json({ error: 'Invalid path' });
  if (!fs.existsSync(absPath)) return res.status(404).json({ error: 'Folder not found' });
  try {
    const entries = fs.readdirSync(absPath).filter(e => e !== '.DS_Store');
    if (entries.length > 0) return res.status(400).json({ error: 'Folder is not empty' });
    fs.rmSync(absPath, { recursive: true });
    logMemoryAction('delete_folder', relPath);
    res.json({ ok: true });
  } catch {
    res.status(500).json({ error: 'Failed to delete folder' });
  }
});

// Rename / move file
app.post('/api/memory/move', (req, res) => {
  const { from, to } = req.body;
  const absFrom = resolveMemoryPath(from);
  const absTo = resolveMemoryPath(to);
  if (!absFrom || !absTo) return res.status(400).json({ error: 'Invalid path' });
  if (!fs.existsSync(absFrom)) return res.status(404).json({ error: 'Source not found' });
  if (fs.existsSync(absTo)) return res.status(409).json({ error: 'Destination already exists' });
  try {
    ensureDir(path.dirname(absTo));
    fs.renameSync(absFrom, absTo);
    logMemoryAction('move', to, { fromPath: from, toPath: to });
    res.json({ ok: true });
  } catch {
    res.status(500).json({ error: 'Failed to move file' });
  }
});

// --- Memory Audit History Endpoints ---

// List log entries with optional filtering + pagination
app.get('/api/memory/history', (req, res) => {
  try {
    const entries = loadAuditLog();
    const { action, path: filterPath, q, limit, offset, from, to } = req.query;
    let filtered = entries;
    if (action) filtered = filtered.filter(e => e.action === action);
    if (filterPath) filtered = filtered.filter(e => e.path && e.path.includes(filterPath));
    if (q) {
      const query = q.toLowerCase();
      filtered = filtered.filter(e =>
        (e.path && e.path.toLowerCase().includes(query)) ||
        (e.action && e.action.toLowerCase().includes(query)) ||
        (e.frontmatter?.name && e.frontmatter.name.toLowerCase().includes(query)) ||
        (e.fromPath && e.fromPath.toLowerCase().includes(query)) ||
        (e.toPath && e.toPath.toLowerCase().includes(query))
      );
    }
    if (from) filtered = filtered.filter(e => e.timestamp >= from);
    if (to) filtered = filtered.filter(e => e.timestamp <= to);
    // Sort newest first
    filtered.sort((a, b) => b.timestamp.localeCompare(a.timestamp));
    const total = filtered.length;
    const off = parseInt(offset) || 0;
    const lim = parseInt(limit) || 50;
    const page = filtered.slice(off, off + lim);
    res.json({ total, offset: off, limit: lim, entries: page });
  } catch {
    res.status(500).json({ error: 'Failed to load history' });
  }
});

// Get single log entry by ID
app.get('/api/memory/history/:id', (req, res) => {
  try {
    const entries = loadAuditLog();
    const entry = entries.find(e => e.id === req.params.id);
    if (!entry) return res.status(404).json({ error: 'Entry not found' });
    res.json(entry);
  } catch {
    res.status(500).json({ error: 'Failed to load entry' });
  }
});

// Get history for a specific file path
app.get('/api/memory/history/file/:filePath(*)', (req, res) => {
  try {
    const entries = loadAuditLog();
    const filePath = req.params.filePath;
    const fileEntries = entries
      .filter(e => e.path === filePath || e.fromPath === filePath || e.toPath === filePath)
      .sort((a, b) => b.timestamp.localeCompare(a.timestamp));
    res.json(fileEntries);
  } catch {
    res.status(500).json({ error: 'Failed to load file history' });
  }
});

// History summary stats
app.get('/api/memory/history-stats', (req, res) => {
  try {
    const entries = loadAuditLog();
    const actionCounts = {};
    const dailyCounts = {};
    const fileCounts = {};
    let totalAdded = 0;
    let totalRemoved = 0;
    for (const e of entries) {
      actionCounts[e.action] = (actionCounts[e.action] || 0) + 1;
      const day = e.timestamp.slice(0, 10);
      dailyCounts[day] = (dailyCounts[day] || 0) + 1;
      if (e.path) fileCounts[e.path] = (fileCounts[e.path] || 0) + 1;
      totalAdded += e.linesAdded || 0;
      totalRemoved += e.linesRemoved || 0;
    }
    // Top 10 most-changed files
    const hotFiles = Object.entries(fileCounts)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 10)
      .map(([p, count]) => ({ path: p, changes: count }));
    res.json({
      totalEntries: entries.length,
      actionCounts,
      dailyCounts,
      hotFiles,
      totalAdded,
      totalRemoved,
      firstEntry: entries.length ? entries[0].timestamp : null,
      lastEntry: entries.length ? entries[entries.length - 1].timestamp : null,
    });
  } catch {
    res.status(500).json({ error: 'Failed to compute history stats' });
  }
});

// Clear all history
app.delete('/api/memory/history', (req, res) => {
  try {
    saveAuditLog([]);
    res.json({ ok: true });
  } catch {
    res.status(500).json({ error: 'Failed to clear history' });
  }
});

// --- Setup / Health Endpoints ---

const { execSync } = require('child_process');

app.get('/api/setup/status', (req, res) => {
  // 1. pm2 status
  let pm2Status = 'unknown';
  try {
    const out = execSync('pm2 jlist 2>/dev/null', { encoding: 'utf-8', timeout: 5000 });
    const list = JSON.parse(out);
    const hub = list.find(p => p.name === 'claude-hub');
    pm2Status = hub ? hub.pm2_env.status : 'not_registered';
  } catch {
    pm2Status = 'not_installed';
  }

  // 2. LaunchAgent
  const launchAgentPath = path.join(os.homedir(), 'Library/LaunchAgents/io.boldteq.claude-hub.plist');
  const launchAgentInstalled = fs.existsSync(launchAgentPath);

  // 3. Agent count
  const agentDir = path.join(CLAUDE_DIR, 'agents');
  const agentCount = fs.existsSync(agentDir)
    ? fs.readdirSync(agentDir).filter(f => f.endsWith('.md')).length
    : 0;

  // 4. SDK location
  const sdkPath = path.join(__dirname, '..', 'sdk');
  const sdkExists = fs.existsSync(path.join(sdkPath, 'package.json'));

  res.json({ pm2Status, launchAgentInstalled, agentCount, sdkExists, port: process.env.PORT || 3847 });
});

app.get('/api/setup/projects', (req, res) => {
  const config = loadConfig();
  const results = [];

  for (const dir of config.projectDirs || []) {
    const resolved = dir.replace(/^~/, HOME);
    if (!fs.existsSync(resolved)) continue;
    try {
      const entries = fs.readdirSync(resolved, { withFileTypes: true });
      for (const entry of entries) {
        if (!entry.isDirectory()) continue;
        if (entry.name.startsWith('.') || entry.name === 'node_modules') continue;
        const projectPath = path.join(resolved, entry.name);
        const hasPackageJson = fs.existsSync(path.join(projectPath, 'package.json'));
        const hasClaudeDir = fs.existsSync(path.join(projectPath, '.claude'));
        const hasClaudeMd = fs.existsSync(path.join(projectPath, 'CLAUDE.md'));
        const hasPubspec = fs.existsSync(path.join(projectPath, 'pubspec.yaml'));
        if (!hasClaudeDir && !hasClaudeMd && !hasPackageJson && !hasPubspec) continue;

        const hasSdk = fs.existsSync(path.join(projectPath, 'node_modules', '@boldteq', 'agents'));
        let hasPackageEntry = false;
        if (hasPackageJson) {
          try {
            const pkg = JSON.parse(fs.readFileSync(path.join(projectPath, 'package.json'), 'utf-8'));
            hasPackageEntry = !!(
              (pkg.dependencies && pkg.dependencies['@boldteq/agents']) ||
              (pkg.devDependencies && pkg.devDependencies['@boldteq/agents'])
            );
          } catch {}
        }

        // Screenshot tool status
        const hasScreenshotScript = fs.existsSync(path.join(projectPath, 'scripts', 'screenshot.mjs'));
        let hasPlaywright = false;
        if (hasPackageJson) {
          try {
            const pkg = JSON.parse(fs.readFileSync(path.join(projectPath, 'package.json'), 'utf-8'));
            hasPlaywright = !!(
              (pkg.dependencies && pkg.dependencies['playwright']) ||
              (pkg.devDependencies && pkg.devDependencies['playwright']) ||
              (pkg.dependencies && pkg.dependencies['@playwright/test']) ||
              (pkg.devDependencies && pkg.devDependencies['@playwright/test'])
            );
          } catch {}
        }
        const hasBrowser = fs.existsSync(path.join(projectPath, 'node_modules', 'playwright'))
          || fs.existsSync(path.join(projectPath, 'node_modules', '.bin', 'playwright'));

        results.push({
          name: entry.name,
          path: projectPath,
          hasSdk,
          hasPackageEntry,
          hasScreenshotScript,
          hasPlaywright,
          hasBrowser,
        });
      }
    } catch {}
  }

  res.json(results);
});

app.post('/api/setup/install-sdk', (req, res) => {
  const { projectPath } = req.body;
  if (!projectPath || typeof projectPath !== 'string') {
    return res.status(400).json({ error: 'projectPath is required' });
  }

  // Validate path exists
  const resolvedProject = path.resolve(projectPath);
  if (!fs.existsSync(resolvedProject) || !fs.statSync(resolvedProject).isDirectory()) {
    return res.status(400).json({ error: 'Project path does not exist' });
  }

  // Validate it's within a known project dir
  const config = loadConfig();
  const allowedRoots = (config.projectDirs || []).map(d => path.resolve(d.replace(/^~/, HOME)));
  const isAllowed = allowedRoots.some(root => resolvedProject.startsWith(root));
  if (!isAllowed) {
    return res.status(403).json({ error: 'Path outside allowed project directories' });
  }

  // Detect project type — Lovable/Vite projects CANNOT use file: deps (breaks remote builds)
  const isLovableOrVite = fs.existsSync(path.join(resolvedProject, 'vite.config.ts'))
    || fs.existsSync(path.join(resolvedProject, 'vite.config.js'));

  const sdkAbsPath = path.resolve(path.join(__dirname, '..', 'sdk'));

  if (isLovableOrVite) {
    // SAFE MODE: Copy a standalone helper file instead of adding file: dependency.
    // file: deps break in Lovable, Vercel, and all CI/CD environments.
    const helperContent = `/**
 * Claude Hub Agent Helper — auto-generated by Claude Hub install-sdk
 * Calls Claude Hub agents via HTTP. No npm dependency required.
 * Claude Hub must be running at localhost:3847 (auto-starts on login).
 *
 * Usage (browser/Vite):
 *   import { callAgent, isOnline } from '@/lib/claudeHub'
 *   const result = await callAgent('quill', 'Write a tagline')
 *
 * NOTE: Only works during local development. Claude Hub is not available
 * in production/deployed environments (Lovable, Vercel, etc.).
 */

const CLAUDE_HUB_URL = import.meta.env.VITE_CLAUDE_HUB_URL || 'http://localhost:3847'

export async function callAgent(agentName, prompt, timeoutMs = 120000) {
  const controller = new AbortController()
  const timeout = setTimeout(() => controller.abort(), timeoutMs)

  try {
    const response = await fetch(\`\${CLAUDE_HUB_URL}/api/playground/run\`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ agentName, prompt }),
      signal: controller.signal,
    })
    clearTimeout(timeout)
    if (!response.ok) throw new Error(\`Claude Hub returned \${response.status}\`)

    const text = await response.text()
    const events = text
      .split('\\n')
      .filter(line => line.startsWith('data: '))
      .map(line => { try { return JSON.parse(line.slice(6)) } catch { return null } })
      .filter(Boolean)

    const errorEvent = events.find(e => e.type === 'error')
    if (errorEvent) return { success: false, output: '', agent: agentName, error: errorEvent.error }

    const doneEvent = events.find(e => e.type === 'done' || e.type === 'complete')
    return { success: true, output: doneEvent?.output || '', agent: agentName }
  } catch (err) {
    clearTimeout(timeout)
    const msg = err instanceof Error ? err.message : String(err)
    return {
      success: false,
      output: '',
      agent: agentName,
      error: msg.includes('abort')
        ? \`Timed out after \${timeoutMs / 1000}s\`
        : \`Claude Hub not reachable — is it running?\`,
    }
  }
}

export async function listAgents() {
  try {
    const res = await fetch(\`\${CLAUDE_HUB_URL}/api/global/agents\`)
    if (!res.ok) throw new Error(\`HTTP \${res.status}\`)
    return await res.json()
  } catch { return [] }
}

export async function isOnline() {
  try {
    const res = await fetch(\`\${CLAUDE_HUB_URL}/api/global/agents\`, { signal: AbortSignal.timeout(3000) })
    return res.ok
  } catch { return false }
}
`;

    // Write helper to src/lib/claudeHub.ts
    const libDir = path.join(resolvedProject, 'src', 'lib');
    if (!fs.existsSync(libDir)) {
      fs.mkdirSync(libDir, { recursive: true });
    }

    const helperPath = path.join(libDir, 'claudeHub.ts');
    fs.writeFileSync(helperPath, helperContent);

    // Add env var hint to .env.local if it exists (or create it)
    const envLocalPath = path.join(resolvedProject, '.env.local');
    let envContent = '';
    if (fs.existsSync(envLocalPath)) {
      envContent = fs.readFileSync(envLocalPath, 'utf-8');
    }
    if (!envContent.includes('VITE_CLAUDE_HUB_URL')) {
      envContent += `\n# Claude Hub — local agent server (only works in dev)\nVITE_CLAUDE_HUB_URL=http://localhost:3847\n`;
      fs.writeFileSync(envLocalPath, envContent);
    }

    res.json({
      success: true,
      method: 'helper-file',
      helperPath: 'src/lib/claudeHub.ts',
      usage: "import { callAgent } from '@/lib/claudeHub'",
      note: 'Lovable/Vite project detected. Installed standalone helper file instead of file: dependency. No npm package needed — works via direct HTTP calls to Claude Hub.',
    });

  } else {
    // NON-VITE PROJECT (e.g., Node.js server): file: dep within same project is OK,
    // but cross-project file: deps still break CI. Use copy if outside project.
    const pkgPath = path.join(resolvedProject, 'package.json');
    let pkg = { name: path.basename(resolvedProject), version: '1.0.0', dependencies: {} };
    if (fs.existsSync(pkgPath)) {
      try {
        pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf-8'));
      } catch {
        return res.status(500).json({ error: 'Could not parse project package.json' });
      }
    }

    // Check if SDK is inside this project (safe) or outside (unsafe for CI)
    const relPath = path.relative(resolvedProject, sdkAbsPath);
    const isInsideProject = !relPath.startsWith('..');

    if (!pkg.dependencies) pkg.dependencies = {};

    if (isInsideProject) {
      // SDK is within the project — file: dep is safe for local-only servers
      pkg.dependencies['@boldteq/agents'] = `file:${relPath}`;
    } else {
      // SDK is outside the project — copy it in to avoid cross-project file: dep
      const targetSdkDir = path.join(resolvedProject, 'lib', 'boldteq-agents');
      fs.mkdirSync(targetSdkDir, { recursive: true });
      const sdkFiles = ['index.js', 'package.json'];
      for (const f of sdkFiles) {
        const src = path.join(sdkAbsPath, f);
        if (fs.existsSync(src)) {
          fs.copyFileSync(src, path.join(targetSdkDir, f));
        }
      }
      pkg.dependencies['@boldteq/agents'] = 'file:lib/boldteq-agents';
    }

    fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2));

    // Run npm install
    try {
      execSync('npm install', { cwd: resolvedProject, timeout: 60000, stdio: 'pipe' });
      res.json({
        success: true,
        method: isInsideProject ? 'file-dep-internal' : 'copy-sdk',
        note: isInsideProject
          ? 'SDK is inside the project — added file: dependency (safe for local servers).'
          : 'SDK was outside the project — copied to lib/boldteq-agents to avoid cross-project file: dep.',
      });
    } catch (err) {
      res.status(500).json({ error: err.message || 'npm install failed' });
    }
  }
});

// ─── Docs ────────────────────────────────────────────────────────────────────
const DOCS_PATH = path.join(__dirname, '..', 'docs');

app.get('/api/docs', (req, res) => {
  if (!fs.existsSync(DOCS_PATH)) return res.json([]);
  const files = fs.readdirSync(DOCS_PATH).filter(f => f.endsWith('.md')).sort();
  const docs = files.map(f => {
    const raw = fs.readFileSync(path.join(DOCS_PATH, f), 'utf-8');
    const firstHeading = raw.split('\n').find(l => l.startsWith('# ')) || '';
    const title = firstHeading.replace(/^# /, '') || f.replace('.md', '');
    // Pull first non-blank, non-heading line as description
    const desc = raw.split('\n').find(l => l.trim() && !l.startsWith('#')) || '';
    return { slug: f.replace('.md', ''), filename: f, title, description: desc.trim() };
  });
  res.json(docs);
});

app.get('/api/docs/:slug', (req, res) => {
  const slug = req.params.slug.replace(/[^a-zA-Z0-9-_]/g, '');
  const filePath = path.join(DOCS_PATH, `${slug}.md`);
  if (!fs.existsSync(filePath)) return res.status(404).json({ error: 'Not found' });
  res.json({ slug, content: fs.readFileSync(filePath, 'utf-8') });
});

// SPA fallback
app.get('*', (req, res) => {
  res.sendFile(path.join(staticPath, 'index.html'));
});

const PORT = process.env.PORT || 3847;
app.listen(PORT, () => {
  console.log('');
  console.log('  ╔══════════════════════════════════════╗');
  console.log('  ║         Claude Hub is running         ║');
  console.log(`  ║     http://localhost:${PORT}            ║`);
  console.log('  ╚══════════════════════════════════════╝');
  console.log('');
  console.log(`  Claude dir: ${CLAUDE_DIR}`);
  console.log(`  Config: ${CONFIG_PATH}`);
  console.log('');
});

