# 6. Install SDK in each project (or use the Install button above)
cd ~/Desktop/Boldteq\\ App/Pinzo && npm install`} />
          </Collapsible>
        </div>
      </section>

      {/* ── Section 4: Troubleshooting ── */}
      <section>
        <SectionHeader
          icon={Shield}
          title="Troubleshooting"
          subtitle="Common issues and exact fixes."
