            },
            {
              problem: 'pm2 shows "errored" with restarts',
              cause: 'Process crashed, usually port conflict or missing dependencies.',
              fix: 'pm2 logs claude-hub  # read the actual error\n# If EADDRINUSE: kill the port (above)\n# If MODULE_NOT_FOUND: npm install in claude-hub/',
            },
            {
