              cause: 'Plist not loaded, wrong Node.js path, or plist syntax error.',
              fix: 'launchctl list | grep claude-hub  # check if registered\n# If missing:\nlaunchctl load ~/Library/LaunchAgents/io.boldteq.claude-hub.plist\n# If wrong node path: edit plist ProgramArguments, then reload',
            },
            {
              problem: 'callAgent() returns "Claude Hub not reachable"',
              cause: 'Claude Hub is not running or running on a different port.',
              fix: 'pm2 status\npm2 restart claude-hub\ncurl http://localhost:3847/api/setup/status',
