            />

            <StatusCard
              icon={Bot}
              title="Global Agents"
              status={(status?.agentCount ?? 0) >= 12 ? 'ok' : (status?.agentCount ?? 0) > 0 ? 'warn' : 'error'}
              statusLabel={
                (status?.agentCount ?? 0) > 0
                  ? `${status?.agentCount} / 12 agents loaded`
