              statusLabel={status?.sdkExists ? 'Ready' : 'Missing'}
              detail="claude-hub/sdk/  (index.js + index.d.ts + package.json)"
              note={
                status?.sdkExists
                  ? 'SDK exists. Projects can install it via npm to call agents programmatically.'
                  : 'SDK folder missing at claude-hub/sdk/. Check that the repo is intact.'
              }
            />
          </div>
