    let addedPlaywright = false;
    if (fs.existsSync(pkgPath)) {
      try {
        const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf-8'));
        const hasPw = (pkg.dependencies?.playwright) || (pkg.devDependencies?.playwright)
          || (pkg.dependencies?.['@playwright/test']) || (pkg.devDependencies?.['@playwright/test']);
        if (!hasPw) {
          if (!pkg.devDependencies) pkg.devDependencies = {};
          pkg.devDependencies['playwright'] = '^1.52.0';
          fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2) + '\n', 'utf-8');
          addedPlaywright = true;
        }
      } catch {}
    }

    // 3. Add .screenshots/ to .gitignore
    const gitignorePath = path.join(resolvedProject, '.gitignore');
    let gitignore = fs.existsSync(gitignorePath) ? fs.readFileSync(gitignorePath, 'utf-8') : '';
    if (!gitignore.includes('.screenshots')) {
      gitignore += '\n# Screenshot tool\n.screenshots/\n';
      fs.writeFileSync(gitignorePath, gitignore, 'utf-8');
    }

    res.json({
      ok: true,
      scriptPath: 'scripts/screenshot.mjs',
      addedPlaywright,
      nextSteps: addedPlaywright
        ? ['npm install', 'npx playwright install chromium', 'node scripts/screenshot.mjs']
        : ['npx playwright install chromium', 'node scripts/screenshot.mjs'],
    });
  } catch (err) {
    res.status(500).json({ error: err.message || 'Install failed' });
  }
});

// ─── Docs ────────────────────────────────────────────────────────────────────
const DOCS_PATH = path.join(__dirname, '..', 'docs');

app.get('/api/docs', (req, res) => {
  if (!fs.existsSync(DOCS_PATH)) return res.json([]);
  const files = fs.readdirSync(DOCS_PATH).filter(f => f.endsWith('.md')).sort();
  const docs = files.map(f => {
    const raw = fs.readFileSync(path.join(DOCS_PATH, f), 'utf-8');
    const firstHeading = raw.split('\n').find(l => l.startsWith('# ')) || '';
    const title = firstHeading.replace(/^# /, '') || f.replace('.md', '');
    // Pull first non-blank, non-heading line as description
    const desc = raw.split('\n').find(l => l.trim() && !l.startsWith('#')) || '';
    return { slug: f.replace('.md', ''), filename: f, title, description: desc.trim() };
  });
  res.json(docs);
});

app.get('/api/docs/:slug', (req, res) => {
  const slug = req.params.slug.replace(/[^a-zA-Z0-9-_]/g, '');
  const filePath = path.join(DOCS_PATH, `${slug}.md`);
  if (!fs.existsSync(filePath)) return res.status(404).json({ error: 'Not found' });
  res.json({ slug, content: fs.readFileSync(filePath, 'utf-8') });
});

// SPA fallback
app.get('*', (req, res) => {
  res.sendFile(path.join(staticPath, 'index.html'));
});

const PORT = process.env.PORT || 3847;
app.listen(PORT, () => {
